// Generated by tools/build.js — edit data/*.json instead.
window.QUESTIONS = [{"id":"extra-001","domain":"sdlc","topic":"CodeDeploy ECS blue/green","difficulty":"hard","scenario":"A company runs a containerized application on Amazon ECS behind an Application Load Balancer and deploys it with AWS CodeDeploy using a blue/green deployment. The team wants to run automated integration tests against the new (green) task set through a test listener on port 8080 before any production traffic is shifted. If the tests fail, the deployment must roll back automatically.","question":"Which solution meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Add a Lambda function to the `AfterAllowTestTraffic` hook in the AppSpec file that runs the tests against the test listener and reports `Failed` to CodeDeploy if they do not pass.","correct":true,"why":"`AfterAllowTestTraffic` runs once the test listener routes to the green task set but before production traffic moves. Reporting `Failed` via `PutLifecycleEventHookExecutionStatus` triggers an automatic rollback."},{"text":"Add a Lambda function to the `AfterAllowTraffic` hook in the AppSpec file that runs the tests and returns `Failed` if they do not pass.","correct":false,"why":"`AfterAllowTraffic` runs after production traffic has already shifted to green, so users would hit the untested version."},{"text":"Add a script to the `ValidateService` hook in the AppSpec file that runs the tests against port 8080.","correct":false,"why":"`ValidateService` is an EC2/on-premises hook and does not exist for ECS deployments; ECS hooks are Lambda functions, not scripts."},{"text":"Configure a CloudWatch Synthetics canary against port 8080 and add an EventBridge rule that calls `StopDeployment` when the canary fails.","correct":false,"why":"This adds moving parts and timing races; lifecycle hooks are the native, synchronous way to gate an ECS blue/green deployment before traffic shifts."}],"takeaway":"\"Test listener\" or \"test traffic\" in an ECS blue/green question means the `AfterAllowTestTraffic` hook.","trap":"Hook from the wrong compute platform (ValidateService is EC2-only)","services":["CodeDeploy","ECS","Lambda"]},{"id":"extra-002","domain":"sdlc","topic":"Cross-account CodePipeline","difficulty":"hard","scenario":"A company has a CI/CD pipeline in AWS CodePipeline in a Tools account. The final stage must deploy an AWS CloudFormation stack into a separate Production account. The first test run fails because the Production account cannot read the pipeline artifacts, which are encrypted with the default AWS managed key `aws/s3`.","question":"Which combination of steps will resolve this? (Select THREE.)","qualifier":null,"select":3,"options":[{"text":"Create a customer managed KMS key in the Tools account, allow the Production account in its key policy, and configure the pipeline artifact store to use this key.","correct":true,"why":"AWS managed keys cannot be shared across accounts. A customer managed key whose key policy grants the Production account `kms:Decrypt` is required for cross-account artifact access."},{"text":"Add a bucket policy to the artifact S3 bucket in the Tools account that allows the Production account to read objects.","correct":true,"why":"The Production account's role also needs S3 permission on the artifact bucket, granted through the bucket's resource policy."},{"text":"Create an IAM role in the Production account that the pipeline in the Tools account can assume, with permissions to deploy CloudFormation, read the artifacts and decrypt them with the KMS key.","correct":true,"why":"CodePipeline performs the cross-account action by assuming a role in the target account (set as the action's `RoleArn`); that role needs the CloudFormation, S3 and KMS permissions."},{"text":"Enable S3 Cross-Region Replication from the artifact bucket to a bucket in the Production account.","correct":false,"why":"Replication copies objects but CodePipeline would still reference its own artifact store; it adds overhead without fixing the KMS sharing problem."},{"text":"Modify the key policy of the AWS managed `aws/s3` key to allow the Production account.","correct":false,"why":"Key policies of AWS managed keys cannot be edited, which is exactly why a customer managed key is needed."},{"text":"Copy the artifacts to the Production account with a Lambda function at the end of each build stage.","correct":false,"why":"A custom copy step is unnecessary operational overhead; native cross-account actions with a shared CMK and assumed role solve it."}],"takeaway":"Cross-account CodePipeline = customer managed KMS key shared via key policy + artifact bucket policy + assumable role in the target account.","trap":"AWS managed keys cannot be shared or edited","services":["CodePipeline","KMS","S3","IAM","CloudFormation"]},{"id":"extra-003","domain":"security","topic":"AWS Config conformance packs","difficulty":"medium","scenario":"A company with 200 AWS accounts in AWS Organizations must ensure that no S3 bucket in any account allows public read access. When a non-compliant bucket is found it must be remediated automatically. New accounts added to the organization must be covered without manual work.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Deploy an AWS Config organization conformance pack from the delegated administrator account that includes the `s3-bucket-public-read-prohibited` rule with automatic remediation using the `AWS-DisableS3BucketPublicReadWrite` SSM Automation document.","correct":true,"why":"Organization conformance packs deploy rules and remediations to every member account, including accounts added later, with fully managed detection and SSM Automation remediation."},{"text":"Deploy a Lambda function in each account with a scheduled EventBridge rule that scans all buckets every hour and removes public access.","correct":false,"why":"Custom code in 200 accounts is high overhead, is not automatically deployed to new accounts and only detects issues hourly."},{"text":"Enable Amazon Macie in every account and configure it to delete public buckets.","correct":false,"why":"Macie discovers sensitive data and reports bucket posture but has no built-in remediation, and deleting buckets is destructive."},{"text":"Use AWS Trusted Advisor to check for public S3 buckets and send a weekly report to the security team through SNS.","correct":false,"why":"A weekly report is neither automatic remediation nor continuous compliance."}],"takeaway":"Org-wide compliance with auto-remediation and coverage of new accounts = AWS Config organization conformance pack (rule + SSM Automation remediation).","trap":"Works but not least overhead (custom Lambda per account)","services":["AWS Config","Organizations","Systems Manager","S3"]},{"id":"extra-004","domain":"sdlc","topic":"SAM DeploymentPreference","difficulty":"medium","scenario":"A team deploys a Lambda-based API using the AWS Serverless Application Model (SAM). New versions must receive 10% of traffic for 10 minutes and then all of it, and the deployment must roll back automatically if the function's error rate rises during the shift. A smoke-test Lambda function must also run before any traffic moves to the new version.","question":"Which SAM configuration meets these requirements?","qualifier":null,"select":1,"options":[{"text":"`AutoPublishAlias: live`, `DeploymentPreference` with `Type: Canary10Percent10Minutes`, `Alarms: [ErrorAlarm]` and `Hooks: PreTraffic: SmokeTestFn`.","correct":true,"why":"Canary10Percent10Minutes shifts 10% then the rest after 10 minutes, the alarm triggers CodeDeploy rollback, and the PreTraffic hook (BeforeAllowTraffic) runs before any shift."},{"text":"`AutoPublishAlias: live`, `DeploymentPreference` with `Type: Linear10PercentEvery10Minutes`, `Alarms: [ErrorAlarm]` and `Hooks: PostTraffic: SmokeTestFn`.","correct":false,"why":"Linear adds 10% every 10 minutes (100 minutes total), not 10% then everything, and a PostTraffic hook runs after traffic has moved."},{"text":"`DeploymentPreference` with `Type: AllAtOnce`, `Alarms: [ErrorAlarm]` and `Hooks: PreTraffic: SmokeTestFn`.","correct":false,"why":"AllAtOnce shifts all traffic immediately, and without `AutoPublishAlias` SAM cannot do gradual deployments at all."},{"text":"`AutoPublishAlias: live`, `DeploymentPreference` with `Type: Canary10Percent10Minutes` and `Hooks: PreTraffic: SmokeTestFn`, plus an EventBridge rule that invokes a Lambda function to point the alias back to the previous version on errors.","correct":false,"why":"Custom rollback logic duplicates what the `Alarms` property already provides natively through CodeDeploy."}],"takeaway":"Canary = one step then all; Linear = equal steps; PreTraffic = before any shift; Alarms = automatic rollback.","trap":"Canary vs Linear naming","services":["SAM","Lambda","CodeDeploy","CloudWatch"]},{"id":"extra-005","domain":"iac","topic":"CloudFormation StackSets","difficulty":"medium","scenario":"A company must deploy a standard set of IAM roles and an AWS CloudTrail configuration to every account in a specific OU. When new accounts are added to that OU the resources must be deployed automatically, and when an account is removed the resources must be deleted.","question":"Which solution requires the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Create a CloudFormation StackSet with service-managed permissions that targets the OU, with automatic deployment enabled and stack retention disabled on account removal.","correct":true,"why":"Service-managed StackSets integrate with Organizations: automatic deployment adds stacks to new accounts in the OU and, with `RetainStacksOnAccountRemoval` false, deletes them when accounts leave."},{"text":"Create a CloudFormation StackSet with self-managed permissions and manually create the `AWSCloudFormationStackSetExecutionRole` in each account.","correct":false,"why":"Self-managed StackSets require roles created in every account and do not support automatic deployment to new accounts."},{"text":"Create an EventBridge rule in the management account for `CreateAccount` events that invokes a Lambda function to deploy a CloudFormation stack into the new account.","correct":false,"why":"Custom code that also misses accounts moved into the OU and does not clean up on removal; StackSets do this natively."},{"text":"Use AWS Systems Manager State Manager associations in each account to create the IAM roles and CloudTrail configuration.","correct":false,"why":"State Manager configures managed instances, not account-level resources, and would still need per-account setup."}],"takeaway":"Deploy to every account in an OU automatically, including new ones = StackSets with service-managed permissions and automatic deployment.","trap":"Self-managed vs service-managed StackSets","services":["CloudFormation","Organizations","IAM","CloudTrail"]},{"id":"iac-001","domain":"iac","topic":"CloudFormation","difficulty":"hard","scenario":"A production AWS CloudFormation stack contains an `AWS::RDS::DBInstance` resource with `DeletionPolicy: Snapshot` and `UpdateReplacePolicy: Delete`. An engineer updated a property that requires replacement, and CloudFormation created a new DB instance and deleted the old one without taking a snapshot. Replacements must remain possible when intended, but the company wants a snapshot of the old instance whenever a replacement happens, and wants engineers to see before executing an update whether it will replace the database.","question":"Which solution meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Set `UpdateReplacePolicy: Snapshot` on the DB instance and require all updates to go through change sets, reviewing the `Replacement` field before execution.","correct":true,"why":"`UpdateReplacePolicy` controls what happens to the old physical resource during a replacement, and change sets show `Replacement: True` before anything changes."},{"text":"Change `DeletionPolicy` to `Retain` and require all updates to go through change sets.","correct":false,"why":"`DeletionPolicy` applies when the resource is removed from the template or the stack is deleted, not when an update replaces it."},{"text":"Apply a stack policy that denies `Update:Replace` on the DB instance and review changes with drift detection.","correct":false,"why":"The stack policy blocks replacements entirely, which the company still needs, and drift detection compares live resources to the template rather than previewing updates."},{"text":"Enable termination protection on the stack and take a manual snapshot before every update.","correct":false,"why":"Termination protection only prevents stack deletion and manual snapshots rely on people remembering; neither previews replacement."}],"takeaway":"DeletionPolicy = resource deleted; UpdateReplacePolicy = resource replaced. Preview replacements with change sets.","trap":"DeletionPolicy does not cover replacement","services":["CloudFormation","RDS"]},{"id":"iac-002","domain":"iac","topic":"CloudFormation","difficulty":"hard","scenario":"A pipeline updates an AWS CloudFormation stack several times a day. The stack contains an Amazon DynamoDB table with logical ID `OrdersTable` that holds production orders. The company must prevent any stack update from replacing or deleting the table, while still allowing non-disruptive changes to the table and all changes to other resources. Rarely, a planned change requires replacing the table, and it must be possible after explicit approval without permanently weakening the protection.","question":"Which solution meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Set a stack policy that allows `Update:*` on all resources and denies `Update:Replace` and `Update:Delete` on `LogicalResourceId/OrdersTable`; for an approved replacement, supply a temporary overriding stack policy for that single update.","correct":true,"why":"Stack policies protect resources from specific update actions, and a stack policy provided during an update applies only to that update."},{"text":"Set `DeletionPolicy: Retain` and `UpdateReplacePolicy: Retain` on the table.","correct":false,"why":"These policies keep the old physical table after a replacement or deletion but do not prevent it; the stack would point to a new empty table."},{"text":"Attach an IAM policy to the pipeline role that denies `cloudformation:UpdateStack` and grant the permission back during approved changes.","correct":false,"why":"This blocks every update to the stack, not only replacement or deletion of the table, and requires permission juggling."},{"text":"Enable termination protection on the stack.","correct":false,"why":"Termination protection only prevents deleting the whole stack; it does not stop updates from replacing or removing a resource."}],"takeaway":"Stack policies prevent unintended updates to specific resources; override them temporarily for a single update.","trap":"Retain policies do not prevent replacement","services":["CloudFormation","DynamoDB"]},{"id":"iac-003","domain":"iac","topic":"AWS Config","difficulty":"hard","scenario":"A company has 60 accounts in AWS Organizations with AWS Config enabled in every account, and the security account is the delegated administrator for AWS Config. The security team wants to deploy a standard set of 15 Config rules, including `cloudformation-stack-drift-detection-check` and S3 public access rules, together with automatic remediation through AWS Systems Manager Automation runbooks. The set must be managed as a single unit and must also apply to accounts that join the organization later.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Write a conformance pack template with the rules and remediation configurations that reference Automation runbooks, and deploy it as an organization conformance pack from the delegated administrator account.","correct":true,"why":"Organization conformance packs deploy rules and remediation actions as one unit to all member accounts, including accounts added later."},{"text":"Deploy each Config rule and remediation with a self-managed CloudFormation StackSet that targets every account ID.","correct":false,"why":"Self-managed StackSets do not deploy automatically to new accounts, and the rules would not be tracked as one compliance unit."},{"text":"Create a Config aggregator in the security account that collects data from all accounts and applies the rules centrally.","correct":false,"why":"An aggregator only aggregates configuration and compliance data; it does not deploy rules or remediation to member accounts."},{"text":"Enable the AWS Foundational Security Best Practices standard in AWS Security Hub for the organization.","correct":false,"why":"Security Hub standards provide a fixed set of controls and do not deploy this custom rule set with Automation remediation as a single unit."}],"takeaway":"Organization conformance packs = Config rules + remediations deployed org-wide as one unit, including new accounts.","trap":"Aggregators view; they do not deploy","services":["AWS Config","Organizations","Systems Manager"]},{"id":"iac-004","domain":"iac","topic":"CloudFormation","difficulty":"hard","scenario":"An AWS CloudFormation stack uses an AWS Lambda-backed custom resource that empties an S3 bucket when the stack is deleted. During a recent deletion, the function raised an exception on the `Delete` request and never responded, so the stack stayed in `DELETE_IN_PROGRESS` for about an hour before failing. The cleanup must still run on deletion, and future failures must surface within minutes instead of an hour.","question":"Which combination of changes meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Wrap the handler logic so that, for `Create`, `Update`, and `Delete` requests alike, it always sends a `SUCCESS` or `FAILED` response to the pre-signed `ResponseURL`, even when an exception occurs.","correct":true,"why":"CloudFormation waits until it receives a response at the `ResponseURL`; an unhandled exception without a response leaves the stack waiting until timeout."},{"text":"Set the `ServiceTimeout` property of the custom resource to a few minutes.","correct":true,"why":"`ServiceTimeout` sets how long CloudFormation waits for a custom resource response (up to 3600 seconds, the default), so a missing response fails fast."},{"text":"Increase the Lambda function timeout to 15 minutes.","correct":false,"why":"The function already fails fast; the stack waits because no response was sent, not because the function ran out of time."},{"text":"Set `DeletionPolicy: Retain` on the custom resource.","correct":false,"why":"With `Retain`, CloudFormation skips deleting the custom resource, so the cleanup logic would never run."},{"text":"Call `cfn-signal` from the Lambda function when processing finishes.","correct":false,"why":"`cfn-signal` sends signals for creation policies and wait conditions; custom resources respond through the `ResponseURL`."}],"takeaway":"Custom resources must always respond to the ResponseURL (use try/finally); ServiceTimeout shortens the wait.","trap":"Raising the Lambda timeout does not fix a missing response","services":["CloudFormation","Lambda","S3"]},{"id":"iac-005","domain":"iac","topic":"CloudFormation","difficulty":"hard","scenario":"An AWS CloudFormation template creates an Auto Scaling group from a launch template. User data runs `cfn-init`, which installs and configures the application from `AWS::CloudFormation::Init` metadata. The stack reaches `CREATE_COMPLETE` while the application is still being installed, and downstream resources start sending traffic too early. The stack must complete only after at least 3 instances are configured successfully and must fail if that has not happened within 15 minutes.","question":"Which combination of steps meets these requirements with the LEAST operational overhead? (Select TWO.)","qualifier":"LEAST operational overhead","select":2,"options":[{"text":"Add a `CreationPolicy` to the Auto Scaling group with `ResourceSignal` `Count: 3` and `Timeout: PT15M`.","correct":true,"why":"A creation policy keeps the Auto Scaling group in `CREATE_IN_PROGRESS` until the required number of success signals arrives or the timeout expires."},{"text":"In user data, run `cfn-signal -e $? --stack <stack-name> --resource <asg-logical-id> --region <region>` right after `cfn-init`.","correct":true,"why":"Passing the `cfn-init` exit code sends success only when configuration succeeded, and a failure signal fails the resource immediately."},{"text":"Add an `UpdatePolicy` with `AutoScalingRollingUpdate` and `WaitOnResourceSignals: true` to the Auto Scaling group.","correct":false,"why":"Update policies apply during stack updates, not during initial resource creation."},{"text":"Add `DependsOn` to the downstream resources that references the Auto Scaling group.","correct":false,"why":"`DependsOn` waits only for the Auto Scaling group resource to be created, not for the application on the instances to be configured."},{"text":"Configure the `cfn-hup` daemon to send the completion signal after `cfn-init` finishes.","correct":false,"why":"`cfn-hup` detects metadata changes and reruns hooks; it does not send creation signals to CloudFormation."}],"takeaway":"CreationPolicy + cfn-signal (with cfn-init's exit code) = stack waits for real instance readiness.","trap":"UpdatePolicy vs CreationPolicy","services":["CloudFormation","EC2 Auto Scaling","EC2"]},{"id":"iac-006","domain":"iac","topic":"CloudFormation","difficulty":"medium","scenario":"A networking team manages a VPC with an AWS CloudFormation stack. Twelve application stacks owned by different teams need the VPC's subnet IDs and security group IDs, and each team deploys on its own schedule. The networking team must be prevented by CloudFormation from removing or changing any of these values while an application stack still uses them.","question":"Which solution meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Export the values from the networking stack's `Outputs` and reference them in the application stacks with `Fn::ImportValue`.","correct":true,"why":"Cross-stack exports decouple lifecycles, and CloudFormation blocks deleting or modifying an export while any stack imports it."},{"text":"Include the networking template as a nested stack inside each application stack.","correct":false,"why":"Each application stack would create and own its own copy of the VPC resources, coupling lifecycles instead of sharing one VPC."},{"text":"Write the values to SSM Parameter Store and reference them with `{{resolve:ssm:...}}` dynamic references.","correct":false,"why":"This shares values but nothing stops the networking team from changing or deleting the parameters while they are in use."},{"text":"Use `Fn::GetAtt` in the application stacks with the networking stack name and logical IDs.","correct":false,"why":"`Fn::GetAtt` only references resources in the same template; it cannot read another stack's resources."}],"takeaway":"Independent stacks sharing values with in-use protection = Export + Fn::ImportValue; nested stacks share a lifecycle.","trap":"Nested stacks vs exports","services":["CloudFormation","Systems Manager","VPC"]},{"id":"iac-007","domain":"iac","topic":"CloudFormation StackSets","difficulty":"hard","scenario":"A company uses AWS Control Tower, and Account Factory provisions new accounts into a `Workloads` OU. Every account in this OU must automatically receive a baseline IAM role and an Amazon EventBridge rule in us-east-1 and eu-central-1. If an account is moved out of the OU, the baseline must be removed from it.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Create a CloudFormation StackSet with service-managed permissions that targets the `Workloads` OU in both Regions, with automatic deployment enabled and stack retention on account removal disabled.","correct":true,"why":"Service-managed StackSets with automatic deployment add stack instances when accounts join the target OU and delete them when accounts leave."},{"text":"Create a self-managed StackSet and an EventBridge rule on the Control Tower `CreateManagedAccount` lifecycle event that invokes a Lambda function to add stack instances.","correct":false,"why":"This works for new accounts but needs custom code and the execution role in every account, and removal on OU moves needs even more code."},{"text":"Share a Service Catalog portfolio containing the baseline product with the `Workloads` OU.","correct":false,"why":"Sharing a portfolio only makes the product available; someone must still launch it in each account and Region."},{"text":"Deploy the IAM role and EventBridge rule in an organization conformance pack.","correct":false,"why":"Conformance packs contain AWS Config rules and remediation configurations, not arbitrary resources like IAM roles and EventBridge rules."}],"takeaway":"Auto-deploy to accounts entering an OU = service-managed StackSet with automatic deployment.","trap":"Self-managed StackSets cannot auto-deploy","services":["CloudFormation StackSets","Control Tower","Organizations"]},{"id":"iac-008","domain":"iac","topic":"Service Catalog","difficulty":"medium","scenario":"A platform team wants developers to launch an approved, preconfigured Amazon RDS for PostgreSQL product in their account through self-service. Developers must not have IAM permissions to create RDS, IAM, or networking resources directly, following least privilege.","question":"Which combination of steps meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Add the product to an AWS Service Catalog portfolio and grant the developers' IAM role access to the portfolio, along with end-user permissions to use Service Catalog.","correct":true,"why":"Portfolio principal associations control who can see and launch products, without granting any rights on the underlying services."},{"text":"Add a launch constraint to the product that specifies an IAM role with the permissions needed to create the product's resources.","correct":true,"why":"Service Catalog assumes the launch constraint role to provision the product, so end users do not need permissions for the underlying resources."},{"text":"Add a template constraint to the product that restricts the allowed instance classes.","correct":false,"why":"Template constraints limit parameter values; they do not provide the permissions needed to provision the resources."},{"text":"Grant the developers `AdministratorAccess` with a permissions boundary that only allows RDS actions.","correct":false,"why":"This gives developers direct RDS permissions, which the requirement forbids, and is far from least privilege."},{"text":"Add a tag update constraint so developers can update the product's tags after launch.","correct":false,"why":"Tag update constraints only control tag edits on provisioned products and have nothing to do with launch permissions."}],"takeaway":"Service Catalog launch constraint role = users provision products without permissions on the underlying services.","trap":"Template constraint vs launch constraint","services":["Service Catalog","IAM","RDS"]},{"id":"iac-009","domain":"iac","topic":"CloudFormation","difficulty":"hard","scenario":"A team updates an AWS CloudFormation stack that changes Amazon API Gateway and AWS Lambda settings. Sometimes an update completes successfully but causes a spike in 5XX errors a few minutes later. The team wants CloudFormation to watch an existing CloudWatch alarm on 5XX errors during each update and for 10 minutes afterward, and to roll the stack back automatically if the alarm goes into ALARM.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Configure the stack's rollback configuration with the alarm as a rollback trigger and a monitoring time of 10 minutes.","correct":true,"why":"Rollback triggers make CloudFormation monitor the specified alarms during the operation and for the monitoring period afterward, rolling back if any goes to ALARM."},{"text":"Create an EventBridge rule for the alarm state change that invokes a Lambda function to call `CancelUpdateStack`.","correct":false,"why":"`CancelUpdateStack` only works while the stack is `UPDATE_IN_PROGRESS`, so it cannot roll back an update that already completed, and it adds custom code."},{"text":"Enable automatic rollback in a CodeDeploy deployment group that uses the alarm.","correct":false,"why":"CodeDeploy rollback applies to CodeDeploy deployments, which are not part of this stack update."},{"text":"Rely on the default stack update behavior, which rolls back when an alarm fires after the update.","correct":false,"why":"By default CloudFormation rolls back only when a resource operation fails; it does not watch alarms unless rollback triggers are configured."}],"takeaway":"CloudFormation rollback triggers = CloudWatch alarms + monitoring time (0-180 minutes) after the operation.","trap":"CancelUpdateStack only during UPDATE_IN_PROGRESS","services":["CloudFormation","CloudWatch","API Gateway","Lambda"]},{"id":"iac-010","domain":"iac","topic":"CloudFormation","difficulty":"hard","scenario":"A company provisions an Amazon RDS for PostgreSQL DB instance with AWS CloudFormation. The master password must never appear in the template, in stack parameters, or in stack events, must be rotated automatically, and the application must retrieve it from AWS Secrets Manager.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Set `ManageMasterUserPassword: true` on the DB instance so that RDS generates the password, stores it in Secrets Manager, and rotates it.","correct":true,"why":"With RDS-managed master passwords, RDS creates the secret and manages rotation (every 7 days by default) without any template-defined secret or rotation function."},{"text":"Pass the password as a stack parameter with `NoEcho: true`.","correct":false,"why":"`NoEcho` masks the value in the console and API output, but the password is still supplied as a parameter and nothing rotates it."},{"text":"Store the password as an SSM Parameter Store `SecureString` and reference it with a `{{resolve:ssm-secure:...}}` dynamic reference.","correct":false,"why":"This keeps the password out of the template, but Parameter Store does not rotate it and the application would not read it from Secrets Manager."},{"text":"Create an `AWS::SecretsManager::Secret` with `GenerateSecretString`, reference it with `{{resolve:secretsmanager:...}}`, and add an `AWS::SecretsManager::SecretTargetAttachment` and `AWS::SecretsManager::RotationSchedule` with a hosted rotation Lambda function.","correct":false,"why":"This works, but it requires defining and maintaining several extra resources and a rotation function that RDS-managed passwords handle natively."}],"takeaway":"For RDS/Aurora master passwords, ManageMasterUserPassword is the lowest-overhead way to get Secrets Manager storage plus rotation.","trap":"Works but more overhead","services":["CloudFormation","RDS","Secrets Manager","Systems Manager"]},{"id":"iac-011","domain":"iac","topic":"CloudFormation","difficulty":"hard","scenario":"A platform team must create an Amazon SNS topic and an Amazon SQS queue subscribed to it for each of 25 microservices. The list of microservice names changes frequently and is passed to the template as a `CommaDelimitedList` parameter. The team wants to avoid copying resource blocks and does not want to write or maintain custom code.","question":"Which solution meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Add `Transform: AWS::LanguageExtensions` to the template and use `Fn::ForEach` to generate the topic, queue, and subscription for each name in the parameter.","correct":true,"why":"The `AWS::LanguageExtensions` transform enables `Fn::ForEach`, which expands resources from a list at deployment time without custom code."},{"text":"Write a CloudFormation macro backed by an AWS Lambda function that duplicates the resources for each name.","correct":false,"why":"A custom macro works, but it is custom code the team would have to write and maintain."},{"text":"Use a nested stack resource with a `Count` property set to the number of microservices.","correct":false,"why":"CloudFormation resources have no `Count` property; that is a Terraform concept."},{"text":"Use the `AWS::Include` transform to include a snippet that contains the three resources.","correct":false,"why":"`AWS::Include` inserts a template snippet from S3 once; it does not loop over a list."}],"takeaway":"Loops in CloudFormation = AWS::LanguageExtensions transform + Fn::ForEach.","trap":"Borrowing Terraform concepts","services":["CloudFormation","SNS","SQS"]},{"id":"iac-012","domain":"iac","topic":"AWS CDK","difficulty":"hard","scenario":"A company uses CDK Pipelines in a tooling account (111111111111) to deploy AWS CDK applications. A DevOps engineer adds a stage that targets a production account (222222222222) in eu-west-1. The pipeline fails with the error: `SSM parameter /cdk-bootstrap/hnb659fds/version not found. Has the environment been bootstrapped?`","question":"What should the DevOps engineer do to resolve the error?","qualifier":null,"select":1,"options":[{"text":"Using credentials for the production account, run `cdk bootstrap aws://222222222222/eu-west-1 --trust 111111111111 --cloudformation-execution-policies <policy ARN with the required permissions>`.","correct":true,"why":"Each target account and Region must be bootstrapped, and `--trust` lets the tooling account assume the bootstrap deployment roles there."},{"text":"Re-run `cdk bootstrap` in the tooling account with `--trust 222222222222`.","correct":false,"why":"This trusts the wrong direction and still leaves the production account and Region without bootstrap resources."},{"text":"Create the `/cdk-bootstrap/hnb659fds/version` parameter manually in the production account.","correct":false,"why":"The parameter only records the bootstrap version; the staging bucket, ECR repository, and deployment roles would still be missing."},{"text":"Run `cdk deploy --require-approval never` from the tooling account.","correct":false,"why":"This only skips security change approval prompts; it does not create the bootstrap resources in the target environment."}],"takeaway":"Bootstrap every target account/Region; cross-account CDK deploys need `--trust <pipeline account>`.","trap":"Bootstrapping the wrong account","services":["AWS CDK","CloudFormation","Systems Manager"]},{"id":"iac-013","domain":"iac","topic":"Systems Manager","difficulty":"hard","scenario":"A company runs 400 Amazon EC2 instances (Amazon Linux 2023 and Windows Server), all managed by AWS Systems Manager. Security patches rated Critical or Important must be installed automatically 7 days after release. Production instances may be patched only on Saturdays from 01:00 to 04:00 UTC, and development instances on Wednesdays at night. Patch compliance must be visible in Patch Manager.","question":"Which combination of steps meets these requirements? (Select THREE.)","qualifier":null,"select":3,"options":[{"text":"Create custom patch baselines for each operating system with approval rules that auto-approve security patches of Critical and Important severity 7 days after release.","correct":true,"why":"Approval rules with an auto-approval delay implement the 7-day waiting period, and separate baselines are needed per OS."},{"text":"Tag instances with the `Patch Group` key (for example `prod` and `dev`) and register the patch groups with the custom baselines.","correct":true,"why":"Patch groups associate instances with a specific patch baseline and make it easy to target each environment."},{"text":"Create a maintenance window for each environment with the required schedule and a Run Command task that runs `AWS-RunPatchBaseline` with `Operation=Install`, targeting the matching patch group.","correct":true,"why":"Maintenance windows enforce the allowed time ranges, and `AWS-RunPatchBaseline` installs approved patches on Linux and Windows and reports compliance."},{"text":"Create EventBridge Scheduler schedules that run `AWS-RunShellScript` with `dnf upgrade --security` on all instances.","correct":false,"why":"This does not patch Windows, ignores the patch baselines, and does not report patch compliance to Patch Manager."},{"text":"Use a maintenance window task that runs the `AWS-ApplyPatchBaseline` document.","correct":false,"why":"`AWS-ApplyPatchBaseline` is a legacy document that supports only Windows; `AWS-RunPatchBaseline` replaces it."},{"text":"Enable automatic patch remediation in Amazon Inspector for the instances.","correct":false,"why":"Inspector detects vulnerabilities but does not install patches on a schedule; patching is done by Patch Manager."}],"takeaway":"Patch Manager = patch baseline (approval rules) + patch groups + maintenance window running AWS-RunPatchBaseline.","trap":"Legacy AWS-ApplyPatchBaseline","services":["Systems Manager","EC2"]},{"id":"iac-014","domain":"iac","topic":"Systems Manager","difficulty":"hard","scenario":"A financial company runs Amazon EC2 instances in private subnets with no NAT gateway or internet gateway. Security policy forbids inbound SSH, open port 22, and bastion hosts. Operators need interactive shell access controlled by IAM, and a full log of every session must be stored in an Amazon S3 bucket encrypted with AWS KMS.","question":"Which combination of steps meets these requirements? (Select THREE.)","qualifier":null,"select":3,"options":[{"text":"Attach an instance profile that includes the `AmazonSSMManagedInstanceCore` managed policy plus permission to write session logs to the S3 bucket and use the KMS key.","correct":true,"why":"The SSM Agent needs core Systems Manager permissions to register, and the instance uploads session logs, so its role needs S3 and KMS permissions too."},{"text":"Create interface VPC endpoints for `ssm`, `ssmmessages`, and `ec2messages`, and a gateway VPC endpoint for Amazon S3.","correct":true,"why":"Without internet access, the agent reaches Systems Manager and the Session Manager channel through these endpoints, and uploads logs through the S3 endpoint."},{"text":"Configure Session Manager preferences to send session logs to the encrypted S3 bucket, and grant operators `ssm:StartSession` on the allowed instances.","correct":true,"why":"Session logging is set in Session Manager preferences, and IAM policies on `ssm:StartSession` control who can open sessions on which instances."},{"text":"Allow inbound TCP 443 in the instances' security group from the Session Manager service IP ranges.","correct":false,"why":"Session Manager needs no inbound rules; the agent initiates outbound HTTPS connections to the endpoints."},{"text":"Create an EC2 Instance Connect Endpoint in the private subnets for operator access.","correct":false,"why":"EC2 Instance Connect Endpoint tunnels SSH to port 22 on the instance, which is forbidden, and does not record session contents."},{"text":"Enable AWS CloudTrail data events to capture every command typed in a session.","correct":false,"why":"CloudTrail records API calls such as `StartSession`, not the commands and output inside a session."}],"takeaway":"Session Manager in a private VPC = instance role + ssm/ssmmessages/ec2messages endpoints (+ S3/CloudWatch for logs); no inbound ports.","trap":"Opening inbound ports for Session Manager","services":["Systems Manager","VPC","S3","KMS","IAM"]},{"id":"iac-015","domain":"iac","topic":"Systems Manager","difficulty":"hard","scenario":"A company must make sure that the Amazon CloudWatch agent is installed and running with a standard configuration on every Amazon EC2 instance tagged `Env=prod`, including instances that Auto Scaling launches later. If someone uninstalls the agent or changes its configuration, it must be corrected automatically within an hour. The agent configuration JSON is about 6 KB and must be stored in AWS Systems Manager Parameter Store.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Store the configuration in an Advanced-tier parameter, and create State Manager associations that target `Env=prod` and run `AWS-ConfigureAWSPackage` for the agent and `AmazonCloudWatch-ManageAgent` with the parameter as the configuration source on a 30-minute schedule.","correct":true,"why":"Advanced-tier parameters hold up to 8 KB, and State Manager applies associations to matching instances when they come online and reapplies them on a schedule to fix drift."},{"text":"Store the configuration in a Standard-tier parameter with higher throughput enabled, and create the same State Manager associations.","correct":false,"why":"Standard-tier parameters are limited to 4 KB regardless of the throughput setting, so the 6 KB configuration cannot be stored."},{"text":"Store the configuration in an Advanced-tier parameter and run `AWS-ConfigureAWSPackage` and `AmazonCloudWatch-ManageAgent` once with Run Command against `Env=prod`.","correct":false,"why":"Run Command runs once against current instances; it does not cover instances launched later or correct drift."},{"text":"Store the configuration in an Advanced-tier parameter and install and configure the agent from user data in the launch template.","correct":false,"why":"User data only runs at first boot of new instances, so existing instances and later uninstalls or config changes are not corrected."}],"takeaway":"Desired state on a schedule, including new instances = State Manager association; Parameter Store Standard 4 KB vs Advanced 8 KB.","trap":"Run Command is one-time; Standard tier is 4 KB","services":["Systems Manager","CloudWatch","EC2 Auto Scaling"]},{"id":"iac-016","domain":"iac","topic":"AppConfig","difficulty":"hard","scenario":"A company runs a serverless checkout service on AWS Lambda. The product team wants to turn a new checkout feature on for customers without deploying code, roll the change out gradually over 30 minutes, and automatically revert the change if a CloudWatch alarm on checkout errors fires during the rollout. Invalid flag values must be rejected before they are deployed.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Create an AWS AppConfig feature flag configuration profile with flag attribute constraints, deploy it with a 30-minute linear deployment strategy to an environment that monitors the CloudWatch alarm, and read the flags in the function through the AWS AppConfig Agent Lambda extension.","correct":true,"why":"AppConfig validates feature flag values, rolls out configuration gradually according to the deployment strategy, and rolls back automatically when an environment's alarm fires."},{"text":"Store the flag in an Advanced-tier SSM parameter with parameter policies and read it from Parameter Store on every invocation.","correct":false,"why":"Parameter policies handle expiration and notifications only; there is no gradual rollout or alarm-based rollback, and per-invocation reads can hit throughput limits."},{"text":"Store the flag as a Lambda environment variable and change it with a CodeDeploy linear deployment that uses the alarm for rollback.","correct":false,"why":"Changing an environment variable requires publishing a new function version and running a deployment, which is the code deployment the team wants to avoid."},{"text":"Use Amazon CloudWatch Evidently feature launches to roll out the flag with alarm-based rollback.","correct":false,"why":"CloudWatch Evidently has been discontinued, and AWS directs feature flag use cases to AWS AppConfig."}],"takeaway":"Feature flags with validation, gradual rollout, and alarm rollback = AWS AppConfig (use the Lambda extension to read them).","trap":"Parameter Store has no gradual rollout","services":["AppConfig","Lambda","CloudWatch","Systems Manager"]},{"id":"incident-001","domain":"incident","topic":"AWS Health","difficulty":"hard","scenario":"A logistics company runs hundreds of EBS-backed EC2 instances across 30 accounts in AWS Organizations. The operations team regularly misses AWS Health notifications about scheduled instance retirements, which causes unplanned outages when AWS stops the instances. The team wants every affected instance to be stopped and started automatically (moving it to healthy hardware) as soon as the retirement event is published, in every current and future account.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Use CloudFormation StackSets with service-managed permissions and automatic deployment to create, in every account, an EventBridge rule matching `source` `aws.health` and `eventTypeCode` `AWS_EC2_PERSISTENT_INSTANCE_RETIREMENT_SCHEDULED`. Target the `AWS-RestartEC2Instance` Systems Manager Automation runbook, using an input transformer to pass the instance ID from the event's `resources` array.","correct":true,"why":"AWS Health events are delivered to EventBridge in the affected account, and EventBridge can start an SSM Automation runbook directly. StackSets automatic deployment adds the rule to new accounts as they join the organization. A stop/start moves an EBS-backed instance to new hardware."},{"text":"Write a Lambda function, scheduled every 15 minutes in the management account, that calls the AWS Health `DescribeEventsForOrganization` API, then assumes a role in each member account to stop and start the affected instances.","correct":false,"why":"This works, but you have to build and maintain polling code and cross-account roles, and the AWS Health API needs a Business, Enterprise On-Ramp, or Enterprise support plan. The event-driven EventBridge approach has far less overhead."},{"text":"Create an AWS Config rule in every account that evaluates EC2 instances for scheduled events and uses automatic remediation with the `AWS-RestartEC2Instance` runbook.","correct":false,"why":"No managed AWS Config rule evaluates AWS Health retirement events. Config records resource configuration changes, not Health notifications, so you would need a custom rule for a problem EventBridge already solves."},{"text":"Enable AWS Health organizational view and subscribe an SNS topic to the Health dashboard so the on-call engineer gets an email and runs the restart runbook through Systems Manager Run Command.","correct":false,"why":"There is no SNS subscription on the Health dashboard itself, and an engineer acting on an email is manual remediation. Run Command also runs commands inside the OS; it cannot stop and start the instance."}],"takeaway":"AWS Health events reach EventBridge (source aws.health) in the affected account, so you can route them straight to an SSM Automation runbook; use StackSets to deploy the rule to every account.","trap":"Polling the Health API instead of reacting to events","services":["AWS Health","EventBridge","Systems Manager","CloudFormation"]},{"id":"incident-002","domain":"incident","topic":"AWS Health","difficulty":"hard","scenario":"A developer at a media company accidentally pushed an IAM user's access key to a public GitHub repository. AWS detected the exposure and sent a notification, but the security team only saw it the next morning. The CISO wants future exposures handled automatically within minutes: the exposed key must be deleted, recent API activity by that key must be summarized, and the security team must be notified.","question":"Which solution meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Create an EventBridge rule that matches AWS Health events with `eventTypeCode` `AWS_RISK_CREDENTIALS_EXPOSED`. Target a Step Functions state machine that deletes the access key with `iam:DeleteAccessKey`, looks up the key's recent activity in CloudTrail with `LookupEvents`, and publishes a summary to an SNS topic.","correct":true,"why":"AWS publishes exposed-credential notifications as AWS Health events of type `AWS_RISK_CREDENTIALS_EXPOSED`, which EventBridge can match. A state machine can then delete the key, query CloudTrail, and notify the team without anyone stepping in."},{"text":"Enable Amazon GuardDuty in the account and create an EventBridge rule that matches the `UnauthorizedAccess:IAMUser/InstanceCredentialExfiltration.OutsideAWS` finding type. Invoke a Lambda function that deletes the access key, queries CloudTrail for the key's recent API calls, and publishes a summary to the security team's SNS topic.","correct":false,"why":"That finding covers temporary EC2 instance-role credentials being used from outside AWS. It is not raised when long-term IAM user keys show up in a public repository, so the exposure would be missed."},{"text":"Enable Amazon Detective and configure it to send the exposed-credential finding to an SNS topic that triggers a Lambda function to delete the key.","correct":false,"why":"Detective is an investigation tool that builds behavior graphs from existing data. It does not detect leaked keys and does not publish findings to SNS."},{"text":"Deploy the `access-keys-rotated` AWS Config managed rule with automatic remediation that deactivates any noncompliant access key.","correct":false,"why":"`access-keys-rotated` only checks key age against `maxAccessKeyAge`. A freshly created key that has been exposed is still compliant, so nothing would be remediated."}],"takeaway":"Leaked IAM keys show up as the AWS Health event AWS_RISK_CREDENTIALS_EXPOSED. Match it with EventBridge and remediate with Step Functions or Lambda.","trap":"Assuming GuardDuty or Detective detects keys leaked to public repos","services":["AWS Health","EventBridge","Step Functions","IAM","CloudTrail"]},{"id":"incident-003","domain":"incident","topic":"Lambda failure handling","difficulty":"hard","scenario":"An e-commerce company processes order events with a Lambda function that S3 and SNS invoke asynchronously. A DLQ is configured today, but the operations team complains that it holds only the original event payload, so they cannot see which retries were exhausted or the full function response. They also want successful invocations recorded on an EventBridge event bus for downstream analytics, and failed events routed to a different EventBridge bus that has its own rules.","question":"Which configuration meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Set an on-success destination and an on-failure destination, each pointing to the appropriate EventBridge event bus, in the function's asynchronous invocation configuration. Tune `MaximumRetryAttempts` and `MaximumEventAgeInSeconds` as needed.","correct":true,"why":"Lambda destinations for asynchronous invocations support EventBridge, SNS, SQS, Lambda, and (for failures) S3. The record they send includes the request payload, the response or error payload, and a `requestContext` showing whether the event failed because retries ran out or because it got too old."},{"text":"Change the DLQ to an SNS topic and subscribe both EventBridge buses to the topic, using SNS filter policies to separate successes from failures.","correct":false,"why":"A DLQ only receives failed events, never successful ones, and EventBridge event buses cannot be SNS subscribers. Even with a different target, the DLQ message still lacks the response payload."},{"text":"Wrap the function code in try/catch blocks that call `PutEvents` to the right event bus on success or failure.","correct":false,"why":"This adds custom code to maintain, and it cannot capture failures that happen outside the handler, such as timeouts or out-of-memory crashes. It also does not know whether Lambda's built-in retries have run out."},{"text":"Configure an event source mapping with `DestinationConfig` and `BisectBatchOnFunctionError` so failed events are split and sent to the failure bus.","correct":false,"why":"Event source mappings exist for poll-based sources such as SQS, Kinesis, and DynamoDB Streams. S3 and SNS invoke Lambda asynchronously, so there is no event source mapping to configure, and bisecting only applies to stream batches."}],"takeaway":"For asynchronous Lambda, destinations beat DLQs: they cover both success and failure, support more target types, and include response and context details.","trap":"DLQ vs destinations","services":["Lambda","EventBridge"]},{"id":"incident-004","domain":"incident","topic":"Lambda event source mapping","difficulty":"hard","scenario":"A fintech company consumes a Kinesis data stream with a Lambda function through an event source mapping that uses the default settings. Last night one malformed record made the function throw repeatedly. The shard stopped making progress for hours while the batch was retried until it expired, and the iterator age alarm fired. The team wants a bad record to be isolated quickly, healthy records to keep flowing, and details of any record that cannot be processed kept for later analysis.","question":"Which combination of event source mapping settings should the team configure? (Select THREE.)","qualifier":null,"select":3,"options":[{"text":"Set `BisectBatchOnFunctionError` to true.","correct":true,"why":"When the function returns an error, Lambda splits the batch in half and retries each half separately. This quickly narrows the failure down to the poison record while the healthy records get processed."},{"text":"Set `MaximumRetryAttempts` (and optionally `MaximumRecordAgeInSeconds`) to a small finite value.","correct":true,"why":"By default, stream event source mappings retry until the record expires (-1, meaning unlimited). A finite limit lets Lambda give up on the bad record and move the shard forward."},{"text":"Configure an on-failure destination (an SQS queue or SNS topic) on the event source mapping.","correct":true,"why":"When retries run out, Lambda sends a record to the destination describing the failed batch: shard ID and starting and ending sequence numbers. You can use it to fetch the records again and analyze them."},{"text":"Configure a dead-letter queue in the Lambda function's `DeadLetterConfig`.","correct":false,"why":"A function-level DLQ applies only to asynchronous invocations. Stream event source mappings invoke the function synchronously and ignore `DeadLetterConfig`."},{"text":"Increase `ParallelizationFactor` to 10 so other batches in the shard can be processed while the bad batch is retried.","correct":false,"why":"Parallelization processes batches concurrently but still keeps records with the same partition key in order. The poison record's partition keeps getting blocked, and nothing ever removes the bad record."},{"text":"Increase the Kinesis stream's data retention period to 7 days.","correct":false,"why":"Longer retention means the bad batch is retried even longer before it expires, which makes the stall worse."}],"takeaway":"For Kinesis or DynamoDB Streams consumers, combine bisect-on-error, finite retries or record age, and an on-failure destination. A function-level DLQ does nothing for stream sources.","trap":"Function DLQ doesn't apply to event source mappings","services":["Lambda","Kinesis Data Streams","SQS"]},{"id":"incident-005","domain":"incident","topic":"Step Functions","difficulty":"medium","scenario":"A travel company's Step Functions Standard workflow (written in JSONPath) calls a Lambda function that charges customers through a third-party payment API. The API sometimes throttles requests, and the function surfaces this as a custom `PaymentThrottled` error. The team wants throttled calls retried with increasing delays. If the call still fails after the retries, the workflow must go to a `RefundAndNotify` state that needs both the original order input and the error details.","question":"Which state machine configuration meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Add a `Retry` field to the task with `ErrorEquals: [\"PaymentThrottled\"]`, `IntervalSeconds`, `BackoffRate`, and `MaxAttempts`. Add a `Catch` field with `ErrorEquals: [\"States.ALL\"]`, `Next: \"RefundAndNotify\"`, and `ResultPath: \"$.error\"`.","correct":true,"why":"Step Functions runs `Retry` first, waiting longer each time based on `BackoffRate`, and falls through to `Catch` only after the retries run out. Setting `ResultPath` to `$.error` adds the error object to the original input instead of replacing it."},{"text":"Add a `Retry` field for `PaymentThrottled` with `IntervalSeconds: 2`, `BackoffRate: 2.0`, and `MaxAttempts: 5`, and a `Catch` field with `ErrorEquals: [\"States.ALL\"]` and `Next: \"RefundAndNotify\"`. Leave `ResultPath` at its default so the error output is passed to the next state.","correct":false,"why":"In a `Catch`, `ResultPath` defaults to `$`, which replaces the state's input with the error output. `RefundAndNotify` would get only the error and lose the original order data."},{"text":"Configure the Lambda function's asynchronous invocation `MaximumRetryAttempts` to 2 and an on-failure destination that starts the `RefundAndNotify` logic.","correct":false,"why":"The Step Functions Lambda integration invokes the function synchronously (RequestResponse), so asynchronous retry and destination settings never apply. The workflow would also lose control of the failure path."},{"text":"Add a `Catch` field for `PaymentThrottled` that loops back to the same task through a `Wait` state, and a second `Catch` for `States.ALL` that goes to `RefundAndNotify`.","correct":false,"why":"A hand-built loop with no counter can retry forever and needs extra states to track attempts. `Retry` with `MaxAttempts` and `BackoffRate` does this natively."}],"takeaway":"Retry runs before Catch. Always set ResultPath in Catch (for example $.error), otherwise the error replaces the original input.","trap":"Catch default ResultPath replaces input","services":["Step Functions","Lambda"]},{"id":"incident-006","domain":"incident","topic":"EventBridge","difficulty":"medium","scenario":"A SaaS company publishes `OrderPlaced` events from its order service to a custom EventBridge event bus. A rule routes them to a billing Lambda function. A bug deployed on Tuesday made the billing function silently ignore some events for 6 hours before it was fixed. The company needs to reprocess exactly the events from that window through the fixed function, and wants to be able to do the same for future incidents.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Create an EventBridge archive on the custom event bus (with an event pattern for `OrderPlaced` and a retention period). After a future incident, start a replay from the archive for the affected time window, targeting the billing rule.","correct":true,"why":"Archives keep events matching a pattern on a bus, and `StartReplay` sends them back to the same bus for a chosen time range, optionally only to selected rules. Note that an archive only covers events received after it is created."},{"text":"Configure an SQS dead-letter queue on the billing rule's target and redrive the messages after the fix.","correct":false,"why":"A target DLQ only catches events EventBridge failed to deliver. Here delivery succeeded and the function ignored the events, so they never reach the DLQ."},{"text":"Use CloudTrail Lake to query the `PutEvents` data events recorded on the custom event bus during the 6-hour window, export the results to S3, and run a script that reads the export and calls `PutEvents` again for each recorded event so the fixed billing function receives them.","correct":false,"why":"CloudTrail records the `PutEvents` API call, not the full event payloads. A custom republishing script is far more work than a replay."},{"text":"Insert an SQS queue between the event bus and the function with a 14-day retention period and replay messages from the queue as needed.","correct":false,"why":"Messages are deleted from the queue after they are processed successfully, so events that were consumed and ignored are gone. SQS has no time-window replay."}],"takeaway":"EventBridge archive and replay lets you reprocess past events by time window after fixing a bug, but the archive must exist before the events arrive.","trap":"Target DLQ only catches delivery failures","services":["EventBridge","Lambda"]},{"id":"incident-007","domain":"incident","topic":"EventBridge cross-account","difficulty":"hard","scenario":"A healthcare company with more than 80 accounts in AWS Organizations wants every GuardDuty finding and every EC2 state-change event from all accounts sent to a custom event bus named `central-ops` in a dedicated operations account. The central team's rules then route the events to its tooling. New accounts are added every month, and the central bus policy should not have to be edited each time.","question":"Which combination of steps meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Add a resource-based policy to the `central-ops` event bus that allows `events:PutEvents` from any principal, with a condition that `aws:PrincipalOrgID` equals the organization ID.","correct":true,"why":"One organization-scoped statement on the event bus policy lets every current and future member account send events, so you never have to add account IDs one by one."},{"text":"Deploy (for example with service-managed StackSets) an EventBridge rule in each member account that matches the required events and targets the ARN of the `central-ops` bus, with an IAM role that allows `events:PutEvents` on that bus.","correct":true,"why":"Events must be forwarded by a rule in the source account whose target is the other account's event bus. StackSets automatic deployment also creates the rule in new accounts."},{"text":"Share the `central-ops` event bus with the organization through AWS Resource Access Manager so member accounts' default buses deliver to it automatically.","correct":false,"why":"EventBridge event buses cannot be shared through AWS RAM. Cross-account delivery uses event bus resource policies plus rules in the source accounts."},{"text":"Create rules on the `central-ops` bus that use each member account's default event bus as the event source.","correct":false,"why":"EventBridge rules only match events already on their own bus. A central account cannot pull events from other accounts' buses; the source accounts have to push them."},{"text":"Add each member account ID to the `central-ops` bus policy with a Lambda function triggered by the Organizations `CreateAccount` CloudTrail event.","correct":false,"why":"This works, but it means maintaining custom automation, and `aws:PrincipalOrgID` already covers new accounts without any changes."}],"takeaway":"Cross-account EventBridge is push-based: rules in the source accounts target the central bus, and an aws:PrincipalOrgID bus policy admits the whole organization.","trap":"Event buses can't be shared via RAM / pulled cross-account","services":["EventBridge","Organizations","CloudFormation"]},{"id":"incident-008","domain":"incident","topic":"Auto Scaling troubleshooting","difficulty":"hard","scenario":"A company's security team required all EBS volumes to be encrypted. The platform team copied the golden AMI with encryption using a customer managed KMS key in the same account and updated the Auto Scaling group's launch template to use the new AMI. Since then, every scale-out activity fails with `Client.InternalError: Client error on launch`, and the instances terminate right away. Launching the same AMI manually as an administrator works.","question":"What should a DevOps engineer do to resolve the issue?","qualifier":null,"select":1,"options":[{"text":"Update the KMS key policy to allow the `AWSServiceRoleForAutoScaling` service-linked role to use the key (`kms:Decrypt`, `kms:GenerateDataKey*`, `kms:ReEncrypt*`, `kms:DescribeKey`, and `kms:CreateGrant`).","correct":true,"why":"Amazon EC2 Auto Scaling launches instances with its service-linked role, which needs permission to use the customer managed key that encrypts the AMI's snapshots. Without it, the volumes can't be created and the launch fails with `Client.InternalError`."},{"text":"Add a statement to the instance profile role used by the launch template that allows `kms:Decrypt`, `kms:GenerateDataKey*`, and `kms:CreateGrant` on the customer managed key, so the instances can decrypt their own EBS volumes when they launch.","correct":false,"why":"The instance profile role is used by software running on the instance after boot. EBS volumes are decrypted at launch on behalf of the Auto Scaling service-linked role, not the instance role."},{"text":"Change the Auto Scaling group health check type from ELB to EC2 so instances are not terminated during startup.","correct":false,"why":"The instances never finish launching, so health checks are not involved. Changing the health check type does not fix a KMS permission error at launch."},{"text":"Request an increase to the EC2 On-Demand vCPU service quota for the Region.","correct":false,"why":"Hitting a quota produces errors like `VcpuLimitExceeded` or `InsufficientInstanceCapacity`, not `Client.InternalError`. Manual launches also work, so capacity is not the problem."}],"takeaway":"Client.InternalError on launch with encrypted AMIs usually means the Auto Scaling service-linked role can't use the KMS key. Fix the key policy, or use a grant if the key is in another account.","trap":"Instance profile vs Auto Scaling service-linked role","services":["EC2 Auto Scaling","KMS","EBS"]},{"id":"incident-009","domain":"incident","topic":"CodeDeploy troubleshooting","difficulty":"hard","scenario":"A company deploys a Java application to an EC2 deployment group with CodeDeploy. Revision 41 deployed successfully, but its `ApplicationStop` hook script had a bug that was found later. Every deployment since then fails in the `ApplicationStop` lifecycle event on all instances, even though the team has fixed the `ApplicationStop` script in revisions 42 and 43. The team needs to get revision 43 deployed.","question":"What is the MOST likely cause and fix?","qualifier":"MOST likely","select":1,"options":[{"text":"`ApplicationStop` runs the script from the last successfully deployed revision (41), so the fix in the new revisions is never used. Redeploy revision 43 with the `ignoreApplicationStopFailures` option (`--ignore-application-stop-failures` in the CLI).","correct":true,"why":"CodeDeploy runs the `ApplicationStop` hook from the previous successful revision's bundle on the instance, because that is the application being stopped. Ignoring `ApplicationStop` failures lets the deployment continue, and after it succeeds, the fixed script becomes the one used next time."},{"text":"The `appspec.yml` file in revision 43 is invalid. Validate it locally and redeploy.","correct":false,"why":"An invalid AppSpec file fails earlier, when the revision is downloaded and the file is parsed. It would not fail consistently at `ApplicationStop` with an old script."},{"text":"The CodeDeploy agent is out of date. Use Systems Manager to update the agent on all instances and redeploy.","correct":false,"why":"An outdated agent does not explain why the failure started after revision 41's buggy script. The new revision's fixed script still won't be the one run at `ApplicationStop`."},{"text":"Change the deployment configuration from `CodeDeployDefault.OneAtATime` to `CodeDeployDefault.AllAtOnce` so the minimum healthy hosts check does not stop the deployment.","correct":false,"why":"The deployment configuration only controls how many instances are deployed at the same time. Every instance would still fail at `ApplicationStop`."}],"takeaway":"ApplicationStop uses the previous successful revision's script. If that script is broken, deploy with ignoreApplicationStopFailures.","trap":"ApplicationStop runs the old revision's script","services":["CodeDeploy","EC2"]},{"id":"incident-010","domain":"incident","topic":"CloudFormation troubleshooting","difficulty":"medium","scenario":"A stack update failed, and CloudFormation's automatic rollback also failed. The stack is now in `UPDATE_ROLLBACK_FAILED`. The events show that rollback could not restore an `AWS::ECS::Service` because someone deleted its target group outside CloudFormation during the incident. The stack contains production databases that must not be replaced, and the team needs the stack updatable again as quickly as possible.","question":"What should the DevOps engineer do?","qualifier":null,"select":1,"options":[{"text":"Run `ContinueUpdateRollback` with the ECS service's logical ID in `ResourcesToSkip`. After the stack reaches `UPDATE_ROLLBACK_COMPLETE`, fix the template so the service and target group match reality.","correct":true,"why":"`ContinueUpdateRollback` is the supported way out of `UPDATE_ROLLBACK_FAILED`. Skipping the resource that can't be restored marks it as rolled back, and the stack becomes updatable without touching the databases."},{"text":"Delete the stack and recreate it from the last known good template.","correct":false,"why":"Deleting the stack would delete (or orphan, with DeletionPolicy) the production databases. That is unnecessary and risky when the rollback can be continued."},{"text":"Run `UpdateStack` with the original template to force the stack back to its previous state.","correct":false,"why":"A stack in `UPDATE_ROLLBACK_FAILED` cannot be updated. You have to finish the rollback first with `ContinueUpdateRollback`."},{"text":"Run drift detection on the stack to identify the deleted target group. Then use a resource import operation to bring a recreated target group back under management, and run `UpdateStack` with the original template to complete the rollback.","correct":false,"why":"Drift detection only reports differences, and resource import and `UpdateStack` are both blocked while the stack is in `UPDATE_ROLLBACK_FAILED`. The rollback has to be finished with `ContinueUpdateRollback` first."}],"takeaway":"To recover from UPDATE_ROLLBACK_FAILED, run ContinueUpdateRollback and add ResourcesToSkip for resources that can't be restored.","trap":"Deleting/updating a stack stuck in UPDATE_ROLLBACK_FAILED","services":["CloudFormation","ECS"]},{"id":"incident-011","domain":"incident","topic":"AWS Config remediation","difficulty":"medium","scenario":"An insurance company's audit found security groups that allow SSH (port 22) from 0.0.0.0/0. The company wants any such rule detected continuously and removed automatically within minutes, with a compliance history kept for auditors. The solution should use managed components wherever possible.","question":"Which combination of steps meets these requirements with the LEAST operational overhead? (Select TWO.)","qualifier":"LEAST operational overhead","select":2,"options":[{"text":"Deploy the `restricted-ssh` AWS Config managed rule and configure automatic remediation with the `AWS-DisableIncomingSSHOnPort22` Systems Manager Automation document, passing the security group ID as the resource parameter.","correct":true,"why":"The managed rule flags security groups that allow 0.0.0.0/0 on port 22, and Config automatic remediation runs the AWS-owned Automation runbook that removes those ingress rules. Config keeps the compliance timeline auditors need."},{"text":"Create an IAM role that Systems Manager Automation can assume, with `ec2:RevokeSecurityGroupIngress` and `ec2:DescribeSecurityGroups` permissions, and pass it as the `AutomationAssumeRole` parameter of the remediation.","correct":true,"why":"Remediation runbooks run with the role passed in `AutomationAssumeRole`. Without a role that trusts `ssm.amazonaws.com` and has permission to revoke ingress, the remediation fails."},{"text":"Write a custom Config rule backed by Lambda that evaluates security groups and calls `RevokeSecurityGroupIngress` from inside the evaluation function.","correct":false,"why":"This could work, but it means maintaining custom code for something a managed rule and AWS-owned runbook already do. Mixing evaluation and remediation also makes compliance history unreliable."},{"text":"Enable AWS Trusted Advisor's security group check and configure weekly email notifications to the security team.","correct":false,"why":"Trusted Advisor flags unrestricted ports but does not remediate. Weekly email does not meet the within-minutes requirement."},{"text":"Enable Amazon Inspector network reachability findings and use Inspector to remove the offending rules.","correct":false,"why":"Inspector reports network exposure but has no remediation actions. It never changes security groups."}],"takeaway":"Config managed rule plus automatic remediation with an AWS-owned SSM runbook plus an AutomationAssumeRole is the low-overhead pattern for detect-and-fix.","trap":"Custom Lambda when managed rule + runbook exists","services":["AWS Config","Systems Manager","IAM"]},{"id":"incident-012","domain":"incident","topic":"Incident Manager","difficulty":"hard","scenario":"A payments company wants a formal incident response process for its checkout service. When the service's composite CloudWatch alarm goes into ALARM, an incident should be opened automatically. The on-call engineer should be paged, and if they don't acknowledge within 10 minutes, the secondary engineer and then the engineering manager should be paged. A diagnostic runbook should start automatically, responders should collaborate in a Slack channel, and a post-incident analysis should be produced afterward.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Use AWS Systems Manager Incident Manager: define contacts and an escalation plan with stages, then create a response plan that engages the escalation plan, starts a Systems Manager Automation runbook, and uses a chat channel configured through Amazon Q Developer in chat applications. Set the response plan as the alarm's action.","correct":true,"why":"Incident Manager provides escalation plans with acknowledgement timeouts, response plans that link runbooks and chat channels, CloudWatch alarm or EventBridge triggers, and built-in post-incident analysis templates."},{"text":"Configure the alarm to publish to an SNS topic that sends SMS to the primary engineer. Add a Lambda function that records the page in DynamoDB, checks for an acknowledgement every 10 minutes, and pages the secondary engineer and then the manager. Start the runbook from the same function and post updates to Slack through a webhook.","correct":false,"why":"This rebuilds escalation and acknowledgement tracking by hand, and still doesn't provide runbooks, a timeline, or post-incident analysis. That is much more overhead."},{"text":"Configure the alarm to create an OpsCenter OpsItem with high severity and assign the OpsItem to the on-call engineer.","correct":false,"why":"OpsItems track operational work, but OpsCenter has no on-call paging, escalation plans, acknowledgement timeouts, or chat channel engagement."},{"text":"Enable AWS Health organizational view and configure AWS User Notifications to email the on-call rotation when the alarm fires.","correct":false,"why":"AWS Health reports AWS service events, not your application alarms, and email notifications provide no escalation or runbook automation."}],"takeaway":"Incident Manager = contacts + escalation plans + response plans (runbook, chat channel, engagements) + post-incident analysis. OpsCenter only tracks work items.","trap":"OpsCenter OpsItems vs Incident Manager incidents","services":["Systems Manager","CloudWatch"]},{"id":"incident-013","domain":"incident","topic":"Fault Injection Service","difficulty":"medium","scenario":"A streaming company wants to confirm that its ECS on Fargate service recovers when a third of its tasks are stopped, running the test in production during low traffic. Leadership requires the experiment to stop automatically and immediately if the customer-facing 5XX error rate on the Application Load Balancer goes above 2% for one minute.","question":"Which approach meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Create an AWS FIS experiment template with the `aws:ecs:stop-task` action targeting 33% of the service's tasks, and add a stop condition that references a CloudWatch alarm on the ALB 5XX error rate metric.","correct":true,"why":"FIS stop conditions are CloudWatch alarms. If an alarm goes into ALARM while the experiment runs, FIS stops the experiment right away, so no custom monitoring code is needed."},{"text":"Create the AWS FIS experiment template with the `aws:ecs:stop-task` action. Then create an EventBridge rule that matches the 5XX alarm's state change to ALARM and invokes a Lambda function that calls the FIS `StopExperiment` API with the ID of the running experiment.","correct":false,"why":"This works, but it adds a rule and a function to do what native stop conditions already do."},{"text":"Write a Step Functions workflow that calls `ecs:StopTask` on randomly selected tasks and checks the alarm state between steps.","correct":false,"why":"This builds a custom chaos tool. Between checks, impact can keep growing, and it lacks FIS's targeting, logging, and safety controls."},{"text":"Use an AWS FIS experiment with the `aws:fis:wait` action set to one minute after stopping tasks, then review the dashboard and stop manually if needed.","correct":false,"why":"Manual review does not meet the requirement for an automatic, immediate stop. A wait action just pauses the experiment and does not guard anything."}],"takeaway":"FIS stop conditions are CloudWatch alarms. Use them to stop an experiment automatically as soon as customer impact crosses a threshold.","trap":"Custom stop logic instead of native stop conditions","services":["Fault Injection Service","CloudWatch","ECS"]},{"id":"incident-014","domain":"incident","topic":"EventBridge API destinations","difficulty":"hard","scenario":"A retail company uses a third-party incident tool that accepts alerts through an HTTPS webhook. The webhook requires an API key in a custom header and a specific JSON body with `summary`, `severity`, and `source` fields. The company wants every CloudWatch alarm state change to ALARM sent to this webhook, with rate limiting so the tool isn't flooded during large outages, and without writing or maintaining code.","question":"Which combination of steps meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Create an EventBridge connection that uses API key authorization with the custom header name, and an API destination for the webhook endpoint with an invocation rate limit.","correct":true,"why":"Connections store the credentials (in an AWS managed Secrets Manager secret) and add the header to each request. API destinations call HTTPS endpoints with a configurable invocations-per-second limit."},{"text":"Create an EventBridge rule matching `CloudWatch Alarm State Change` events where `detail.state.value` is `ALARM`, with the API destination as the target and an input transformer that maps event fields into the required `summary`, `severity`, and `source` JSON template.","correct":true,"why":"An input transformer extracts values from the event with `InputPathsMap` and builds a new body with `InputTemplate`. It reshapes the event payload without any Lambda function."},{"text":"Subscribe the webhook URL to an SNS topic using the HTTPS protocol and configure the alarms to publish to the topic.","correct":false,"why":"SNS HTTPS deliveries use SNS's own JSON envelope and require the endpoint to confirm the subscription. You can't set a custom API key header or build the vendor's body format."},{"text":"Configure the input transformer to call the CloudWatch `DescribeAlarms` API and add the alarm's threshold and metric history to the payload.","correct":false,"why":"Input transformers only reshape data already in the event. They can't call APIs or add outside data; that would need EventBridge Pipes enrichment or a Lambda function."},{"text":"Create a Lambda function that formats the alarm and posts it to the webhook, with reserved concurrency set to 1 for rate limiting.","correct":false,"why":"This works, but it goes against the no-code requirement and means maintaining HTTP client code, retries, and secret handling yourself."}],"takeaway":"EventBridge API destination plus connection plus input transformer delivers to third-party webhooks with auth and rate limits, no code needed. Input transformers reshape the event; they can't fetch data.","trap":"Input transformers can't enrich with external data","services":["EventBridge","CloudWatch","Secrets Manager"]},{"id":"monitoring-001","domain":"monitoring","topic":"CloudWatch agent","difficulty":"medium","scenario":"A company runs 300 Amazon Linux EC2 instances across several Auto Scaling groups. The operations team needs memory utilization and free disk space for every instance in CloudWatch, including instances launched in the future, so it can create alarms. All instances are already managed by AWS Systems Manager.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Store a CloudWatch agent configuration in Systems Manager Parameter Store, and use a State Manager association targeted by tag to install the `AmazonCloudWatchAgent` package and apply that configuration. Attach `CloudWatchAgentServerPolicy` to the instance role.","correct":true,"why":"Memory and disk usage are OS-level metrics that EC2 doesn't publish; the CloudWatch agent collects them. A tag-targeted State Manager association automatically applies the agent and its configuration to new instances too."},{"text":"Enable detailed monitoring on the launch templates so EC2 publishes memory and disk metrics every minute.","correct":false,"why":"Detailed monitoring only changes the default EC2 metrics (CPU, network, disk I/O for instance store, status checks) from 5-minute to 1-minute periods. It never adds memory or filesystem usage."},{"text":"Create CloudWatch Logs metric filters on `/var/log/messages` that extract memory and disk values from the system log.","correct":false,"why":"The system log doesn't report memory or disk utilization at regular intervals. Something would still have to ship the logs, and metric filters can only parse log text that exists."},{"text":"Add a cron job to each AMI that runs a script calling `PutMetricData` with memory and disk values every minute.","correct":false,"why":"This works, but the team would have to maintain custom scripts, AMI rebuilds, and credentials handling. The managed agent does the same job with less overhead."}],"takeaway":"EC2 memory and disk-space metrics require the CloudWatch agent; roll it out at scale with Systems Manager State Manager and Parameter Store.","trap":"Detailed monitoring does not add memory metrics","services":["CloudWatch","Systems Manager","EC2"]},{"id":"monitoring-002","domain":"monitoring","topic":"CloudWatch Logs metric filters","difficulty":"medium","scenario":"A payments service running on Amazon ECS on AWS Fargate sends application logs to the CloudWatch Logs group `/ecs/payments`. When a charge fails, the service logs a JSON line with `\"event\":\"PAYMENT_FAILED\"`. The on-call team must be paged through an existing SNS topic whenever more than 10 failures occur within 5 minutes.","question":"Which solution meets this requirement with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Create a metric filter on the log group with the pattern `{ $.event = \"PAYMENT_FAILED\" }` that publishes a count metric, then create a CloudWatch alarm on the metric's 5-minute Sum > 10 that notifies the SNS topic.","correct":true,"why":"Metric filters turn matching log events into a CloudWatch metric, and alarms can watch that metric. The alarm then publishes to SNS, and all of it is managed configuration with no code."},{"text":"Create a subscription filter on the log group that sends matching events directly to a CloudWatch alarm with a threshold of 10.","correct":false,"why":"CloudWatch alarms only evaluate metrics. They can't receive log events. Subscription filters deliver to Kinesis Data Streams, Firehose, Lambda, or OpenSearch Service."},{"text":"Create an EventBridge rule with an event pattern that matches `PAYMENT_FAILED` log lines from the log group and targets the SNS topic.","correct":false,"why":"CloudWatch Logs doesn't emit each ingested log line as an EventBridge event, so the rule would never match. EventBridge also can't count events over a 5-minute window."},{"text":"Schedule a Lambda function every minute that calls `FilterLogEvents`, counts failures over the last 5 minutes, and publishes to SNS.","correct":false,"why":"It works, but it adds custom code, scheduling, and API throttling concerns. The native metric filter and alarm do the same thing with no code."}],"takeaway":"Logs to alarm means log group, then metric filter, then metric, then alarm. Alarms only watch metrics.","trap":"Alarms only watch metrics","services":["CloudWatch Logs","CloudWatch","SNS","ECS"]},{"id":"monitoring-003","domain":"monitoring","topic":"Embedded metric format","difficulty":"hard","scenario":"A retail company's checkout Lambda function handles 3,000 requests per second at peak. Product managers want custom business metrics, such as cart value and items per order, broken down by `PaymentMethod` and `Country`. Early tests that called `PutMetricData` from the function added latency and hit API throttling. The team also wants to keep the raw per-request values for later investigation.","question":"Which solution meets these requirements with the LEAST impact on function latency?","qualifier":"LEAST impact on function latency","select":1,"options":[{"text":"Write each data point to standard output as a structured JSON log in CloudWatch embedded metric format (EMF), declaring the metrics and the `PaymentMethod` and `Country` dimensions in the `_aws` metadata.","correct":true,"why":"CloudWatch extracts metrics from EMF log events asynchronously, so the function makes no synchronous metric API calls. The full JSON event, with its raw values, stays in CloudWatch Logs for Logs Insights queries."},{"text":"Enable CloudWatch Lambda Insights on the function and add the business fields as Lambda Insights custom dimensions.","correct":false,"why":"Lambda Insights collects system-level performance metrics such as memory, CPU, init duration, and network. It doesn't provide business metrics or custom dimensions like cart value."},{"text":"Batch the values in memory and call `PutMetricData` with up to 1,000 metric data points per request at the end of each invocation.","correct":false,"why":"Batching cuts the number of calls, but each invocation still makes a synchronous network call that adds latency and can be throttled at 3,000 RPS. Raw values are also not kept for investigation."},{"text":"Log plain-text lines and create one metric filter per payment-method and country combination to publish the metrics.","correct":false,"why":"Maintaining one filter per dimension combination doesn't scale and is brittle, and there are quotas on metric filters per log group. EMF declares dimensions inside the log event itself."}],"takeaway":"Embedded metric format publishes high-volume custom metrics through logs, asynchronously, with no PutMetricData calls, and keeps the raw events queryable.","trap":"Lambda Insights is for system metrics, not business metrics","services":["CloudWatch","CloudWatch Logs","Lambda"]},{"id":"monitoring-004","domain":"monitoring","topic":"Composite alarms","difficulty":"hard","scenario":"An SRE team gets paged too often. It has separate CloudWatch alarms for ALB p99 latency, the 5XX error rate, and RDS CPU, and each pages independently, often for brief blips. The team wants one page only when high latency AND a high error rate occur together. It also wants to suppress that page while a deployment is running; deployments are signaled by an existing alarm named `DeploymentInProgress`.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Remove the actions from the individual alarms and create a composite alarm with the rule `ALARM(LatencyHigh) AND ALARM(ErrorRateHigh)`, an SNS action, and `DeploymentInProgress` configured as its actions suppressor alarm.","correct":true,"why":"Composite alarms combine other alarms' states with Boolean logic. With an actions suppressor, they hold back their actions while the suppressor alarm is in ALARM, so there's one page, only when both conditions hold, and none during deployments."},{"text":"Create an EventBridge rule that matches both alarms' state changes in a single event pattern and invokes SNS only when both arrive within 5 minutes.","correct":false,"why":"EventBridge rules evaluate each event on its own and have no state, so a pattern can't require two separate events to have occurred. Correlating them would need extra code."},{"text":"Use metric math to multiply the latency metric by the error-rate metric and alarm when the product exceeds a threshold.","correct":false,"why":"The product of two metrics isn't a reliable AND, because one very high value can trip it while the other is normal. It also doesn't handle deployment suppression."},{"text":"Increase the evaluation periods on every alarm to 15 minutes and disable actions on them with a script during each deployment.","correct":false,"why":"Longer evaluation periods delay real alerts and still page separately for each alarm. A script that disables and re-enables actions adds overhead that the composite alarm's actions suppressor already handles."}],"takeaway":"Use composite alarms (AND/OR/NOT of alarm states) with an actions suppressor to cut alert noise.","trap":"EventBridge can't correlate two separate events","services":["CloudWatch","SNS","EventBridge"]},{"id":"monitoring-005","domain":"monitoring","topic":"Metric math and anomaly detection","difficulty":"hard","scenario":"A streaming company has an ALB in front of its API. It needs two alerts. The first must fire when 5XX responses from targets exceed 2% of all requests. The second must fire when target response time departs from its normal pattern, which follows a strong daily and weekly seasonality that makes any fixed threshold either noisy or blind at night. The team wants no custom code.","question":"Which actions should the DevOps engineer take? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Create an alarm on a metric math expression `100 * m1 / m2`, where m1 is `HTTPCode_Target_5XX_Count` (Sum) and m2 is `RequestCount` (Sum), with a threshold of 2.","correct":true,"why":"CloudWatch alarms can evaluate a metric math expression, so the error rate is computed on the fly from the two ALB metrics without any code."},{"text":"Create a CloudWatch anomaly detection alarm on `TargetResponseTime` that triggers when the metric goes above the band.","correct":true,"why":"Anomaly detection trains a model on the metric's history, including daily and weekly seasonality, and the alarm compares values to the expected band rather than a fixed threshold."},{"text":"Create an alarm on `HTTPCode_Target_5XX_Count` with a static threshold of 2.","correct":false,"why":"This alarms on an absolute count of 2 errors, not on a 2% share of requests. It would be noisy at peak traffic and meaningless at low traffic."},{"text":"Schedule a Lambda function that computes the error rate every minute and publishes it as a custom metric to alarm on.","correct":false,"why":"It works, but it's custom code that the requirement excludes. Metric math does the same thing natively."},{"text":"Enable CloudWatch Container Insights on the ALB to get an automatic error-rate metric and latency baseline.","correct":false,"why":"Container Insights collects metrics for ECS, EKS, and Kubernetes clusters. It isn't a feature of an ALB and doesn't create baselines or rate alarms."}],"takeaway":"Alarm on ratios with metric math expressions, and on seasonal metrics with anomaly detection bands.","trap":"Counts vs rates; static thresholds on seasonal data","services":["CloudWatch","ELB"]},{"id":"monitoring-006","domain":"monitoring","topic":"Cross-account log centralization","difficulty":"hard","scenario":"A company has 80 AWS accounts in AWS Organizations, and new accounts are added monthly. The security team wants application log events from every account streamed in near real time into a single Amazon Data Firehose stream in a central logging account, which delivers them to a third-party SIEM. The solution must cover new log groups and new accounts automatically and must not allow accounts outside the organization to send data.","question":"Which combination of steps meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"In the logging account, create a CloudWatch Logs destination that targets the Firehose stream, with a destination access policy that allows `logs:PutSubscriptionFilter` on the condition `aws:PrincipalOrgID` equals the organization ID.","correct":true,"why":"A CloudWatch Logs destination is the cross-account target for subscription filters, and it supports Kinesis Data Streams and Firehose. Scoping its policy with aws:PrincipalOrgID admits only the organization's accounts, including new ones."},{"text":"In each member account, create an account-level subscription filter policy (`PutAccountPolicy` with type `SUBSCRIPTION_FILTER_POLICY`) that points to the destination ARN, and roll it out with CloudFormation StackSets using service-managed automatic deployment.","correct":true,"why":"An account-level subscription filter policy applies to all current and future log groups in the account. StackSets with automatic deployment applies it to new accounts as they join the organization."},{"text":"Create a CloudWatch cross-account observability sink in the logging account and link every member account to it so the logs flow into the Firehose stream.","correct":false,"why":"Observability Access Manager sinks and links let a monitoring account view and query source accounts' telemetry. They don't stream log events into Firehose or another delivery pipeline."},{"text":"Schedule a `CreateExportTask` every 5 minutes in each account to export log groups to an S3 bucket in the logging account, and trigger Firehose from S3.","correct":false,"why":"Export tasks are batch jobs that can take up to 12 hours, and only one can run per account at a time, so this isn't near real time. Firehose also can't use S3 as a source."},{"text":"Create subscription filters in each member account that send directly to the Firehose stream ARN in the logging account, with no destination resource.","correct":false,"why":"Cross-account subscription delivery goes through a CloudWatch Logs destination in the receiving account. Per-log-group filters also wouldn't automatically cover new log groups."}],"takeaway":"Cross-account log streaming means a Logs destination (Kinesis or Firehose) with an org-scoped policy, plus subscription filters (an account-level policy) in the source accounts; OAM is for viewing, not shipping.","trap":"OAM shares telemetry for viewing, it does not stream logs","services":["CloudWatch Logs","Firehose","Organizations","CloudFormation"]},{"id":"monitoring-007","domain":"monitoring","topic":"CloudWatch cross-account observability","difficulty":"medium","scenario":"A platform team operates a central monitoring account for 25 workload accounts in one AWS Organization. Engineers want to sign in only to the monitoring account and from there search logs, build dashboards and alarms on metrics, and open the X-Ray trace map across all workload accounts, without copying the telemetry.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Configure CloudWatch cross-account observability: create an Observability Access Manager sink in the monitoring account that shares metrics, logs, and traces, and create links from every workload account, for example with a CloudFormation StackSet across the organization.","correct":true,"why":"With OAM sinks and links, the monitoring account can query metrics, logs, and traces from the source accounts in place, with no copying. Cross-account alarms, Logs Insights queries, and the trace map then work in one console."},{"text":"Stream all workload-account logs and metrics with subscription filters and metric streams into the monitoring account, and re-ingest them there.","correct":false,"why":"This copies and pays for the telemetry twice and adds pipelines to operate, and traces still aren't covered. The requirement says not to copy."},{"text":"Create an IAM role in each workload account and have engineers switch roles into each account to view CloudWatch.","correct":false,"why":"Role switching gives access, but engineers still see one account at a time. There's no single cross-account search, dashboard, or trace map."},{"text":"Enable an organization trail in CloudTrail and query it from the monitoring account with CloudTrail Lake.","correct":false,"why":"CloudTrail records API activity. It doesn't contain application logs, CloudWatch metrics, or X-Ray traces."}],"takeaway":"CloudWatch cross-account observability (OAM sink and links) gives one monitoring account in-place access to metrics, logs, and traces from many accounts.","trap":"Copying telemetry when it can be shared","services":["CloudWatch","X-Ray","CloudFormation"]},{"id":"monitoring-008","domain":"monitoring","topic":"AWS X-Ray","difficulty":"hard","scenario":"A company runs a Java service on Amazon ECS with the EC2 launch type. The code is already instrumented with the X-Ray SDK, but no traces appear in the X-Ray console. The task definition has a single container. Support engineers also want to search traces by `customerTier` (for example, `gold`) to see whether premium customers are affected by latency issues.","question":"Which combination of actions meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Add the X-Ray daemon as a sidecar container in the task definition, listening on UDP port 2000, and grant the task role `xray:PutTraceSegments` and `xray:PutTelemetryRecords`, for example with `AWSXRayDaemonWriteAccess`.","correct":true,"why":"The SDK sends segments over UDP to a daemon on port 2000, and the daemon uploads them to the X-Ray API. Without a daemon, or an ADOT collector, and the IAM permissions, nothing reaches X-Ray."},{"text":"Record `customerTier` as an annotation on the segment.","correct":true,"why":"Annotations are indexed key-value pairs, so they can be used in filter expressions such as `annotation.customerTier = \"gold\"` to search traces."},{"text":"Record `customerTier` as metadata on the segment.","correct":false,"why":"Metadata is stored with the trace but isn't indexed, so it can't be used in filter expressions to search for traces."},{"text":"Allow inbound TCP port 2000 from 0.0.0.0/0 in the container instance's security group so that the X-Ray service can pull traces from the application.","correct":false,"why":"X-Ray never pulls traces. The SDK pushes segments over UDP to a local daemon, which pushes them outbound to the X-Ray API, so opening inbound ports to the internet is useless and insecure."},{"text":"Create a sampling rule with a fixed rate of 100% so that all requests are sent to X-Ray.","correct":false,"why":"Sampling controls how many requests are recorded, but no traces arrive at all because there's no daemon. Raising sampling to 100% also increases cost without fixing the root cause."}],"takeaway":"X-Ray needs a daemon or ADOT collector on UDP 2000 plus IAM permissions, and only annotations, not metadata, are searchable.","trap":"Annotations vs metadata","services":["X-Ray","ECS","IAM"]},{"id":"monitoring-009","domain":"monitoring","topic":"Amazon Managed Service for Prometheus","difficulty":"hard","scenario":"A company runs several Amazon EKS clusters whose workloads already expose Prometheus metrics endpoints. It currently runs self-managed Prometheus servers that keep running out of disk and lose data during upgrades. The company wants a managed, highly available Prometheus-compatible store with PromQL support and long retention, plus managed dashboards that engineers sign in to with their existing AWS IAM Identity Center identities. The team does not want to run scraping agents itself if possible.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Create an Amazon Managed Service for Prometheus workspace, configure an AWS managed collector (scraper) for each EKS cluster, and create an Amazon Managed Grafana workspace that uses IAM Identity Center authentication and the Prometheus workspace as a data source.","correct":true,"why":"Managed Service for Prometheus is a managed, highly available, PromQL-compatible store, and its managed collectors scrape EKS without agents in the cluster. Managed Grafana supports IAM Identity Center sign-in and has a native data source for it."},{"text":"Enable CloudWatch Container Insights on each cluster and build CloudWatch dashboards with PromQL queries.","correct":false,"why":"Container Insights collects its own set of container metrics, not your existing Prometheus metrics in a PromQL-compatible store. The requirement is specifically a managed Prometheus backend with Grafana dashboards."},{"text":"Run Prometheus with Thanos sidecars on each cluster, store blocks in S3, and self-host Grafana on EKS with SAML.","correct":false,"why":"This can solve retention, but the team keeps operating Prometheus, Thanos, and Grafana itself, which is the overhead it wants to get rid of."},{"text":"Send the Prometheus metrics to Amazon OpenSearch Service and use OpenSearch Dashboards with fine-grained access control.","correct":false,"why":"OpenSearch is a search and log analytics engine, not a Prometheus-compatible time-series store. Existing PromQL queries and Grafana dashboards wouldn't carry over."}],"takeaway":"For managed Prometheus on AWS, use Amazon Managed Service for Prometheus (with managed collectors or ADOT) and Amazon Managed Grafana with IAM Identity Center sign-in.","trap":"Container Insights is not a Prometheus backend","services":["Managed Service for Prometheus","Managed Grafana","EKS","IAM Identity Center"]},{"id":"monitoring-010","domain":"monitoring","topic":"AWS CloudTrail","difficulty":"hard","scenario":"Auditors at a bank discovered that objects were deleted from a regulated S3 bucket, and nobody could say which principal did it. The bank uses AWS Organizations with 40 accounts. It now requires a record of who reads or deletes objects in its regulated buckets across all accounts. It also requires being able to prove to auditors that the audit log files were not modified or deleted after delivery.","question":"Which combination of actions meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Create an organization trail from the management account (or a delegated administrator account) and enable S3 data events for the regulated buckets.","correct":true,"why":"Object-level operations such as GetObject and DeleteObject are data events, which trails don't log by default. An organization trail applies the configuration to every member account, including new ones."},{"text":"Enable CloudTrail log file integrity validation on the trail.","correct":true,"why":"Integrity validation delivers hourly digest files signed with SHA-256 hashing and RSA signing. Running `validate-logs` proves whether any log file was modified or deleted after delivery."},{"text":"Keep the default trail configuration, because `DeleteObject` is recorded as a management event.","correct":false,"why":"Bucket-level calls such as DeleteBucket are management events, but object-level calls such as DeleteObject and GetObject are data events, which must be enabled explicitly."},{"text":"Enable CloudTrail Insights so that unauthorized object deletions are detected and attributed to the principal.","correct":false,"why":"CloudTrail Insights detects unusual API call volume or error rates against a baseline. It doesn't log individual object reads or deletes, or who made them."},{"text":"Enable S3 server access logging and present the access logs to auditors as the tamper-proof record.","correct":false,"why":"Server access logs are delivered on a best-effort basis and have no built-in integrity validation. CloudTrail data events with digest files are the verifiable audit record."}],"takeaway":"Object-level S3 API calls are CloudTrail data events, which you must turn on; log file integrity validation proves the logs weren't tampered with.","trap":"DeleteObject is a data event, not a management event","services":["CloudTrail","S3","Organizations"]},{"id":"monitoring-011","domain":"monitoring","topic":"ALB access logs","difficulty":"hard","scenario":"Customers of a SaaS company report intermittent slow responses. The ALB access logs are already delivered to an S3 bucket. The team must find, for the last 7 days, which client IP addresses and request paths had the slowest backend processing, separate from time spent in the load balancer, and it wants to use SQL without provisioning any servers or clusters.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Create an Amazon Athena table over the access log prefix, using partition projection on the date, and query it ordered by `target_processing_time`, grouped by `client:port` and request URL.","correct":true,"why":"Athena queries the logs in S3 serverlessly. The `target_processing_time` field measures the time from the load balancer sending the request to the target until the target starts sending response headers, which isolates backend latency."},{"text":"Run a CloudWatch Logs Insights query on the ALB access logs, sorted by `request_processing_time`.","correct":false,"why":"ALB access logs are delivered only to S3, not to CloudWatch Logs. `request_processing_time` also measures the load balancer's own time, not the backend's."},{"text":"Load the logs into an Amazon OpenSearch Service domain with an ingestion pipeline and build an OpenSearch Dashboards visualization.","correct":false,"why":"OpenSearch can analyze these logs, but provisioning a domain and an ingestion pipeline for a one-off 7-day SQL question goes against the no-clusters, least-overhead requirement."},{"text":"Alarm on the ALB `TargetResponseTime` metric and use its dimensions to identify the slowest client IP addresses.","correct":false,"why":"`TargetResponseTime` is aggregated per load balancer, target group, and AZ. CloudWatch metrics have no client IP or path dimensions, so per-request details come only from the access logs."}],"takeaway":"ALB access logs live in S3, so query them with Athena; target_processing_time is backend time, while request and response processing times are the load balancer's.","trap":"ALB access logs are not in CloudWatch Logs","services":["ELB","Athena","S3"]},{"id":"monitoring-012","domain":"monitoring","topic":"VPC Flow Logs","difficulty":"medium","scenario":"A security team suspects that malware on some EC2 instances is resolving command-and-control domain names. The VPC uses the Amazon-provided DNS resolver. VPC Flow Logs are enabled for the VPC, but the team cannot find any DNS activity or domain names in them. The team needs the domain names queried and the source instances.","question":"Which solution meets this requirement?","qualifier":null,"select":1,"options":[{"text":"Enable Route 53 Resolver query logging for the VPC and send the logs to CloudWatch Logs or S3.","correct":true,"why":"Resolver query logging records each DNS query from the VPC, with the queried domain name, record type, response code, and source IP and instance ID."},{"text":"Change the flow log record format to include the `pkt-dst-aws-service` and `flow-direction` fields, which add the DNS query name.","correct":false,"why":"These are real flow log fields, but flow logs only record IP-level connection metadata, never packet payloads such as domain names. Flow logs also don't capture traffic to the Amazon-provided DNS resolver at all."},{"text":"Turn on VPC Traffic Mirroring for the Amazon DNS resolver's network interface.","correct":false,"why":"The Amazon-provided resolver (the VPC base +2 address) isn't an ENI you can select as a mirror source, and mirroring would require running packet-analysis appliances, which is far more overhead."},{"text":"Create a CloudWatch Logs metric filter on the flow log group that matches UDP port 53 and extracts the domain name.","correct":false,"why":"Traffic to the Amazon DNS resolver isn't in flow logs, and even other DNS flows contain no domain names for a filter to extract."}],"takeaway":"VPC Flow Logs don't capture traffic to the Amazon DNS resolver, the instance metadata service, Amazon Time Sync, or DHCP, and never include payloads; use Resolver query logging for DNS.","trap":"What VPC Flow Logs do NOT show","services":["VPC","Route 53 Resolver","CloudWatch Logs"]},{"id":"monitoring-013","domain":"monitoring","topic":"CloudWatch Logs data protection","difficulty":"medium","scenario":"During an audit, a company discovers that a legacy application occasionally writes full credit card numbers and email addresses into the CloudWatch Logs group `/app/legacy`. Fixing the code will take months. Until then, developers who read the logs must not see this data, while a small incident-response group must still be able to view the original values when necessary.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Attach a CloudWatch Logs data protection policy to the log group with the managed data identifiers for credit card numbers and email addresses, and grant `logs:Unmask` only to the incident-response group.","correct":true,"why":"Data protection policies detect and mask sensitive data as it is ingested, so masked values appear in the console, Logs Insights, and subscriptions. Only principals with logs:Unmask can view the original values."},{"text":"Add a subscription filter that sends events to a Lambda function that redacts card numbers and writes the events back into the same log group.","correct":false,"why":"The original unmasked events stay in the log group. Writing events back into the same group the filter watches also creates a processing loop."},{"text":"Create a metric filter that matches card number patterns and replaces them with asterisks.","correct":false,"why":"Metric filters only generate metrics from matching events. They never change or mask the stored log data."},{"text":"Encrypt the log group with a customer managed KMS key and allow only the incident-response group to use the key.","correct":false,"why":"KMS encryption protects data at rest, but anyone allowed to read the log group sees decrypted plaintext. Restricting the key would block developers from the logs entirely instead of masking specific fields."}],"takeaway":"CloudWatch Logs data protection policies mask sensitive data at ingestion; only principals with logs:Unmask can see the original values.","trap":"Metric filters and KMS don't mask log content","services":["CloudWatch Logs","IAM","KMS"]},{"id":"monitoring-014","domain":"monitoring","topic":"Amazon Data Firehose","difficulty":"hard","scenario":"An IoT company streams JSON telemetry records into an Amazon Data Firehose stream that delivers to S3. Analysts query the data with Athena and complain about slow, expensive scans of raw JSON. Compliance also requires removing the `deviceOwnerEmail` field from every record before it is stored. The company wants to keep the pipeline serverless and avoid batch jobs.","question":"Which combination of changes meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Enable Firehose data transformation with a Lambda function that removes the `deviceOwnerEmail` field and returns each record with result `Ok`.","correct":true,"why":"Firehose invokes the transformation Lambda function on buffered batches before delivery, so the field is removed in-stream and never lands in S3."},{"text":"Enable Firehose record format conversion to Apache Parquet, using a table schema defined in the AWS Glue Data Catalog.","correct":true,"why":"Firehose can convert JSON input to Parquet or ORC using a schema from the Glue Data Catalog. Columnar files greatly reduce the data Athena scans and the query cost."},{"text":"Add an S3 event notification on the destination bucket that invokes a Lambda function to rewrite each new object as Parquet without the email field, into the same bucket and prefix.","correct":false,"why":"Writing the rewritten object back to the same bucket and prefix triggers the notification again, which creates a recursive loop. The raw objects with emails would also be stored, even briefly."},{"text":"Run a nightly AWS Glue ETL job that converts the raw JSON to Parquet and drops the email field.","correct":false,"why":"It works for the format, but it's the batch job the company wants to avoid, and raw records with emails would sit in S3 until the job runs."},{"text":"Enable Firehose dynamic partitioning with a JQ expression that deletes the `deviceOwnerEmail` field.","correct":false,"why":"Dynamic partitioning uses JQ expressions to extract partition keys for the S3 prefix. It doesn't change or remove fields from the records."}],"takeaway":"Firehose can transform records with Lambda and convert JSON to Parquet or ORC via a Glue schema in-stream, so you don't need S3-triggered rewrites, which can loop.","trap":"S3 event writing back to the same bucket creates a loop","services":["Firehose","Lambda","Glue","Athena","S3"]},{"id":"monitoring-015","domain":"monitoring","topic":"CloudWatch Synthetics","difficulty":"medium","scenario":"An online bank's login page has failed twice in the last month because of a broken third-party JavaScript dependency, while the servers stayed healthy and every infrastructure alarm stayed green. Real users found the problem first. The bank wants to detect such failures proactively by running the full login flow (load page, submit credentials of a test user, verify the dashboard renders) every 5 minutes and alert the team when the flow fails.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Create a CloudWatch Synthetics canary with a scripted browser workflow (Puppeteer, Playwright, or Selenium runtime) on a 5-minute schedule, with test credentials in Secrets Manager, and a CloudWatch alarm on the canary's `SuccessPercent` metric.","correct":true,"why":"Canaries run headless-browser scripts on a schedule from outside your application, publish `SuccessPercent` and `Duration` metrics, and save screenshots and HAR files that help diagnose front-end failures."},{"text":"Create a Route 53 health check with string matching against the login page URL and an alarm on the health check status.","correct":false,"why":"A Route 53 health check fetches a URL and can match a string in the first bytes of the response, but it can't run JavaScript, submit a form, or verify that the dashboard renders."},{"text":"Enable CloudWatch RUM on the login page and alarm when JavaScript errors increase.","correct":false,"why":"RUM monitors real users' sessions, so it still depends on real users hitting the failure. It doesn't proactively run a scripted login every 5 minutes."},{"text":"Schedule a Lambda function every 5 minutes that sends an HTTP GET to the login page and publishes a custom metric if the response is not 200.","correct":false,"why":"The page returned 200 while broken JavaScript stopped login from working, so a status code check would miss it. Building a headless browser into Lambda by hand is what Synthetics already provides."}],"takeaway":"Use CloudWatch Synthetics canaries for proactive, scripted user-journey checks; alarm on SuccessPercent.","trap":"Simple HTTP checks miss front-end failures","services":["CloudWatch Synthetics","CloudWatch","Secrets Manager","Route 53"]},{"id":"resilience-001","domain":"resilience","topic":"Aurora Global Database","difficulty":"hard","scenario":"A fintech company runs its ledger on an Aurora PostgreSQL global database with the primary cluster in us-east-1 and a secondary cluster in us-west-2. Regulators require a semiannual DR drill in which the writer role moves to us-west-2 for one week and then moves back. The drill must not lose any committed transactions, and the team does not want to rebuild replication or re-create clusters after each move. Both Regions are healthy during the drill.","question":"Which approach meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Run a global database switchover (`switchover-global-cluster`) to make the us-west-2 cluster the primary, then run another switchover back to us-east-1 after the drill.","correct":true,"why":"Switchover (formerly called managed planned failover) waits for the secondary to fully catch up, so RPO is zero, and it reverses the roles while keeping the global database topology intact. The old primary becomes a secondary automatically, so nothing has to be rebuilt."},{"text":"Detach the us-west-2 cluster from the global database with `remove-from-global-cluster`, promote it to a standalone writer, and add us-east-1 back as a secondary after the drill.","correct":false,"why":"Detach-and-promote is the manual path for an unplanned Regional outage. It breaks replication, so the global database has to be rebuilt afterward, and writes that hadn't replicated yet can be lost. That is far more overhead than a switchover."},{"text":"Run `failover-global-cluster` with the `--allow-data-loss` option to move the writer to us-west-2, then repeat the command to move it back.","correct":false,"why":"The allow-data-loss failover is meant for unplanned outages when the primary Region is impaired. It does not wait for replication to catch up, so committed transactions can be lost, which breaks the zero-data-loss requirement."},{"text":"Create a cross-Region read replica of the primary cluster in us-west-2, promote it during the drill, and use AWS DMS to sync changes back to us-east-1 afterward.","correct":false,"why":"This rebuilds what the global database already does natively, and it adds DMS tasks and a one-way promotion. The team would have to rebuild replication after every drill."}],"takeaway":"For planned Aurora Global Database Region moves, use switchover: RPO is zero and the topology is preserved. Use failover with allow-data-loss, or detach-and-promote, only for real outages.","trap":"Using the unplanned-outage procedure for a planned drill","services":["Aurora","RDS"]},{"id":"resilience-002","domain":"resilience","topic":"DR strategies","difficulty":"hard","scenario":"A logistics company runs an order-management application in eu-west-1 on EC2 instances in an Auto Scaling group behind an ALB, with data in Amazon Aurora MySQL. The business has set a disaster recovery objective of RTO 1 hour and RPO under 1 minute for a full Regional outage. Finance asks that as little as possible run in the DR Region until a disaster happens.","question":"Which DR strategy meets the objectives in the MOST cost-effective way?","qualifier":"MOST cost-effective","select":1,"options":[{"text":"Pilot light: add an Aurora Global Database secondary cluster in eu-central-1, pre-provision the ALB and an Auto Scaling group with desired capacity 0 from a replicated AMI, and scale out and repoint DNS during a disaster.","correct":true,"why":"Continuous storage-level replication to the secondary cluster typically keeps RPO around a second, and only the data tier runs all the time. Scaling a pre-built Auto Scaling group from 0 and promoting the database fits comfortably within a 1-hour RTO."},{"text":"Backup and restore: use AWS Backup to copy daily Aurora snapshots and AMIs to eu-central-1, and restore the full stack with CloudFormation during a disaster.","correct":false,"why":"It is the cheapest option, but daily snapshot copies give an RPO measured in hours, and even continuous backups are not replicated across Regions in near real time. It fails the sub-minute RPO requirement."},{"text":"Warm standby: run a scaled-down but fully functional copy of the application in eu-central-1 with a few always-on EC2 instances and an Aurora Global Database secondary, then scale up during a disaster.","correct":false,"why":"Warm standby meets the RTO and RPO, but it keeps compute running all the time. The 1-hour RTO leaves enough time to start compute from zero, so paying for idle instances is unnecessary."},{"text":"Multi-site active-active: serve production traffic from both Regions with Route 53 latency routing and Aurora Global Database write forwarding.","correct":false,"why":"Active-active gives near-zero RTO but costs the most, because both Regions run at production scale. That is overkill for a 1-hour RTO."}],"takeaway":"Pick the cheapest DR strategy that still meets both RTO and RPO: backup/restore means hours, pilot light means tens of minutes with live data, warm standby means minutes, and active-active means near zero.","trap":"Over-engineering with warm standby or active-active when pilot light meets the objectives","services":["Aurora","EC2 Auto Scaling","Route 53","AWS Backup"]},{"id":"resilience-003","domain":"resilience","topic":"RDS Multi-AZ","difficulty":"medium","scenario":"A SaaS company runs Amazon RDS for PostgreSQL as a Single-AZ instance. Read-heavy reporting queries regularly slow down the transactional workload. The company needs automatic failover to another Availability Zone with no committed transactions lost, and it wants to offload reporting reads to the same infrastructure that provides the high availability. The team does not want to migrate to a different database engine.","question":"Which deployment option meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Convert the database to an RDS Multi-AZ DB cluster deployment, which has a writer and two readable standby instances in three AZs, and point reporting at the cluster reader endpoint.","correct":true,"why":"A Multi-AZ DB cluster uses semisynchronous replication to two standbys that also serve reads through the reader endpoint. Failover is automatic and typically completes in under 35 seconds, so one feature covers both HA and read offload."},{"text":"Convert the database to a Multi-AZ DB instance deployment and point reporting queries at the standby instance's endpoint.","correct":false,"why":"In a Multi-AZ DB instance deployment, the standby cannot be read. It exists only for failover, and there is no endpoint to query it."},{"text":"Create two cross-AZ read replicas, point reporting at them, and configure RDS to promote a replica automatically if the primary fails.","correct":false,"why":"Read replicas replicate asynchronously and RDS never promotes them automatically. Promotion is a manual or scripted action, and transactions that hadn't replicated yet can be lost."},{"text":"Keep the Single-AZ instance, put Amazon RDS Proxy in front of it, and enable the proxy's read/write splitting to send reporting queries to a standby.","correct":false,"why":"RDS Proxy pools connections and can shorten failover time, but it does not create standbys or make Single-AZ highly available. Read routing still needs real reader instances behind it."}],"takeaway":"The standby in a Multi-AZ DB instance deployment cannot be read. A Multi-AZ DB cluster (MySQL/PostgreSQL) gives two readable standbys and fast automatic failover.","trap":"Assuming the Multi-AZ instance standby can serve reads","services":["RDS","RDS Proxy"]},{"id":"resilience-004","domain":"resilience","topic":"DynamoDB global tables","difficulty":"medium","scenario":"A gaming company stores player profiles in a DynamoDB table in us-east-1. It is launching in Europe and wants players there to read and write their profiles with single-digit-millisecond latency from eu-west-1, while US players keep using us-east-1. If one Region fails, the other Region must keep accepting writes for all players. For the rare simultaneous update to the same profile, the company accepts last-writer-wins conflict resolution.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Add an eu-west-1 replica to the existing table to turn it into a DynamoDB global table, and have each regional application stack use its local replica.","correct":true,"why":"Global tables give fully managed multi-active replication, so writes are accepted in every replica Region. Concurrent updates resolve with last writer wins, which the company accepts, and there is no replication code to maintain."},{"text":"Create a separate table in eu-west-1 and enable DynamoDB Streams on both tables, with Lambda functions that copy each change to the other Region.","correct":false,"why":"This can work, but the team has to own the replication code, retries, loop prevention, and conflict handling. That is the overhead global tables remove."},{"text":"Create a DynamoDB Accelerator (DAX) global cluster spanning both Regions so that European writes are cached locally and flushed to us-east-1.","correct":false,"why":"DAX is a regional, in-memory read-through/write-through cache. There is no multi-Region DAX global cluster, and writes still go to the single base table."},{"text":"Enable point-in-time recovery and schedule an hourly cross-Region export and import of the table into eu-west-1 for European players.","correct":false,"why":"Exports and imports are batch jobs. The European copy would be up to an hour stale and could not take local writes that sync back, so this is not active-active."}],"takeaway":"DynamoDB global tables are the managed answer for multi-Region active-active DynamoDB; the default mode resolves conflicts with last writer wins.","trap":"Hand-rolled Streams replication or a non-existent multi-Region DAX","services":["DynamoDB","Lambda"]},{"id":"resilience-005","domain":"resilience","topic":"S3 Cross-Region Replication","difficulty":"hard","scenario":"A media company keeps 1.2 PB of video masters in a versioned S3 bucket in us-east-1. A new business-continuity policy requires a copy of every object, including all objects that already exist, in a bucket in us-west-2. For new uploads, the policy requires replication within 15 minutes backed by an AWS SLA, and the company wants replication-latency metrics in CloudWatch.","question":"Which combination of actions meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Create a versioned destination bucket in us-west-2 and an S3 Replication rule with S3 Replication Time Control (RTC) enabled.","correct":true,"why":"RTC is designed to replicate 99.99% of new objects within 15 minutes, comes with an SLA, and automatically enables replication metrics such as ReplicationLatency and OperationsPendingReplication. Versioning must be enabled on both buckets."},{"text":"Run an S3 Batch Replication job to replicate the objects that existed before the replication rule was created.","correct":true,"why":"Live replication rules only apply to objects uploaded after the rule exists. S3 Batch Replication is the supported way to backfill existing objects, and objects that previously failed to replicate, to the destination."},{"text":"Enable the replication rule's \"replicate existing objects automatically\" flag so the live rule backfills the existing objects in the background within the RTC window.","correct":false,"why":"Live replication rules have no such flag. Existing objects need a Batch Replication job, and the RTC 15-minute target applies only to new objects."},{"text":"Enable S3 Transfer Acceleration on the source bucket so that replication traffic uses the CloudFront edge network and meets the 15-minute target.","correct":false,"why":"Transfer Acceleration speeds up client uploads to and downloads from a bucket over long distances. It has no effect on S3 replication and provides no replication SLA."},{"text":"Schedule an AWS DataSync task every 15 minutes between the two buckets and publish task metrics to CloudWatch.","correct":false,"why":"DataSync can copy between buckets, but a scheduled task is not continuous replication and carries no 15-minute replication SLA. It also adds an extra service to operate when native replication already meets the need."}],"takeaway":"Use S3 RTC when you need a 15-minute replication SLA and metrics, and Batch Replication to backfill objects that existed before the rule.","trap":"Assuming live replication copies existing objects","services":["S3","CloudWatch","DataSync"]},{"id":"resilience-006","domain":"resilience","topic":"Route 53 health checks","difficulty":"hard","scenario":"A company exposes an internal API to other VPCs through a Route 53 private hosted zone record `api.corp.internal`. The primary copy runs on EC2 instances behind an internal Network Load Balancer in one VPC, and a standby copy runs behind another internal NLB in a second VPC that is associated with the same private hosted zone. The company wants DNS to fail over automatically to the standby when the primary NLB has no healthy targets. The NLBs have no public IP addresses.","question":"How should the DevOps engineer configure the failover?","qualifier":null,"select":1,"options":[{"text":"Create a CloudWatch alarm on the primary NLB's `HealthyHostCount` metric, create a Route 53 health check that monitors that alarm's state, and attach it to the primary record of a failover routing policy.","correct":true,"why":"Route 53 health checkers run on the public internet and cannot reach private IP addresses. A health check based on a CloudWatch alarm's state works for private resources and can drive failover records in a private hosted zone."},{"text":"Create a Route 53 HTTP endpoint health check that targets the private IP address of the primary NLB, and attach it to the primary failover record.","correct":false,"why":"Endpoint health checks come from Route 53 health checkers on the internet, which cannot route to private VPC addresses. The check would always fail and cause a permanent failover."},{"text":"Configure an EventBridge rule that matches the NLB target health change event and sends it directly to the Route 53 failover record to switch to the secondary.","correct":false,"why":"Route 53 records are not EventBridge targets, and failover routing is driven only by health checks. This design also invents an event-to-record integration that doesn't exist."},{"text":"Use a weighted routing policy with weight 100 on the primary and 0 on the standby, and rely on the NLB's own cross-zone failover to shift traffic.","correct":false,"why":"NLB cross-zone load balancing spreads traffic across AZs inside one load balancer. It cannot send traffic to a different NLB in another VPC, and nothing would change the weights automatically."}],"takeaway":"Route 53 health checkers cannot reach private endpoints; for private resources, use health checks based on CloudWatch alarms.","trap":"Endpoint health checks against private IPs","services":["Route 53","CloudWatch","ELB"]},{"id":"resilience-007","domain":"resilience","topic":"Route 53 Application Recovery Controller","difficulty":"hard","scenario":"A payments company runs identical active-passive stacks in us-east-1 and us-west-2, with Route 53 failover records in front. After an industry incident, the CTO requires that operators can fail over manually with one action that keeps working even if a Region, including the Route 53 control plane, is impaired. The CTO also requires a guardrail that prevents both Regions from being switched off at the same time by mistake.","question":"Which solution meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Create a Route 53 Application Recovery Controller cluster with a routing control per Region tied to the failover records through routing control health checks, add an assertion safety rule that at least one routing control is On, and flip states through the cluster's Regional endpoints.","correct":true,"why":"ARC routing controls are changed through a highly available data plane: a cluster with five Regional endpoints. Changing them doesn't depend on the Route 53 control plane. Safety rules enforce invariants such as keeping at least one Region On."},{"text":"Write a runbook that calls `ChangeResourceRecordSets` to swap the record values to us-west-2, and store an SCP that blocks deleting both records at once.","correct":false,"why":"`ChangeResourceRecordSets` is a Route 53 control-plane API, and AWS recommends against depending on control-plane changes during recovery. SCPs control IAM authorization, not the routing state of both Regions."},{"text":"Enable ARC readiness checks on both stacks so that Route 53 automatically fails over when the passive Region is reported ready.","correct":false,"why":"Readiness checks only audit whether the resources and quotas in the replica stack match. They never shift traffic, and they don't give operators a manual failover switch."},{"text":"Lower the TTL on the failover records to 1 second and have operators deliberately fail the primary's Route 53 health check by stopping the primary ALB.","correct":false,"why":"Breaking production to trigger a health check is fragile, has no guardrail against taking both Regions down, and still requires changes in the impaired Region."}],"takeaway":"ARC routing controls give a data-plane-backed manual failover switch with safety rules; readiness checks only audit and never move traffic.","trap":"Relying on Route 53 control-plane APIs during recovery","services":["Route 53 ARC","Route 53"]},{"id":"resilience-008","domain":"resilience","topic":"Auto Scaling lifecycle hooks","difficulty":"medium","scenario":"A company runs a batch-processing fleet on EC2 instances in an Auto Scaling group. Each instance writes processing logs to local disk, and auditors require every log to be uploaded to Amazon S3 before an instance goes away, including instances removed during scale-in. The upload takes up to 4 minutes. The team already uses AWS Systems Manager on all instances.","question":"Which solution meets these requirements MOST reliably?","qualifier":"MOST reliably","select":1,"options":[{"text":"Add an `autoscaling:EC2_INSTANCE_TERMINATING` lifecycle hook, use an EventBridge rule on the lifecycle action event to start a Systems Manager Run Command that uploads the logs, and have the script call `complete-lifecycle-action` when it finishes.","correct":true,"why":"The terminating lifecycle hook holds the instance in the Terminating:Wait state until the heartbeat timeout (default 3600 seconds) expires or `complete-lifecycle-action` is called. That guarantees time for the upload before termination."},{"text":"Add a shutdown script to the instance through user data that uploads the logs to S3 when the operating system receives the shutdown signal.","correct":false,"why":"OS shutdown scripts get a short, uncontrolled window and aren't guaranteed to finish a 4-minute upload. Nothing makes Auto Scaling wait for them."},{"text":"Increase the target group deregistration delay to 300 seconds so the instance stays alive long enough to upload its logs.","correct":false,"why":"Deregistration delay only lets in-flight load balancer requests drain. It doesn't run the upload, and this batch fleet may not even sit behind a load balancer."},{"text":"Enable instance scale-in protection on all instances and remove it with a Lambda function after a nightly log upload.","correct":false,"why":"Scale-in protection blocks scale-in until removed and doesn't cover health-check replacements. A nightly upload also misses logs written between runs, which is an overly complex workaround for what lifecycle hooks do natively."}],"takeaway":"Use a terminating lifecycle hook to run custom work before an Auto Scaling instance is terminated, then call complete-lifecycle-action.","trap":"Confusing deregistration delay with lifecycle hooks","services":["EC2 Auto Scaling","EventBridge","Systems Manager"]},{"id":"resilience-009","domain":"resilience","topic":"Auto Scaling warm pools","difficulty":"hard","scenario":"An e-commerce company's application servers take about 9 minutes to boot because they load a large product catalog into memory and warm a local cache. Traffic spikes come from flash promotions that marketing announces with no notice, so the spikes are unpredictable. During spikes, new instances join too late and customers see errors. The company wants faster scale-out but does not want to pay for idle running compute.","question":"Which solution meets these requirements in the MOST cost-effective way?","qualifier":"MOST cost-effective","select":1,"options":[{"text":"Add a warm pool to the Auto Scaling group with the pool state set to Stopped, and use a lifecycle hook so the instances run the full bootstrap before they are stopped in the pool.","correct":true,"why":"Instances in a Stopped warm pool have already done their slow initialization, and you pay only for their EBS volumes while they wait. On scale-out they start much faster than a cold launch."},{"text":"Enable predictive scaling on the Auto Scaling group so that capacity is launched ahead of the spikes.","correct":false,"why":"Predictive scaling forecasts from recurring daily or weekly patterns in historical load. Unannounced flash promotions don't follow such patterns, so it can't launch capacity ahead of them."},{"text":"Raise the group's minimum capacity to the peak size observed during the last promotion.","correct":false,"why":"This works, but it keeps peak-sized running compute all the time, which is exactly the idle cost the company wants to avoid."},{"text":"Lower the target tracking policy's target value and shorten the default instance warmup to 60 seconds so new instances are counted sooner.","correct":false,"why":"Instance warmup only controls when a new instance's metrics count toward scaling decisions. It doesn't shorten the 9-minute boot, so instances still serve traffic too late."}],"takeaway":"Warm pools pre-initialize instances; use the Stopped state to cut scale-out latency while paying only for storage.","trap":"Predictive scaling for unpredictable spikes","services":["EC2 Auto Scaling"]},{"id":"resilience-010","domain":"resilience","topic":"Auto Scaling and ELB health","difficulty":"hard","scenario":"A web application runs on EC2 instances in an Auto Scaling group registered with an ALB target group. The team sees two problems. When the application process hangs, the ALB marks the target unhealthy, but the instance stays in service for hours and is never replaced. During scale-in, users with long-running report downloads (up to 2 minutes) get their connections cut. A previous engineer set the target group's deregistration delay to 5 seconds.","question":"Which combination of changes resolves both problems? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Turn on Elastic Load Balancing health checks for the Auto Scaling group (health check type ELB), keeping an appropriate health check grace period.","correct":true,"why":"With only EC2 status checks, Auto Scaling sees a hung application as healthy because the instance is still running. Turning on ELB health checks makes Auto Scaling replace instances that the target group reports as unhealthy."},{"text":"Increase the target group's deregistration delay to about 150 seconds.","correct":true,"why":"Deregistration delay (connection draining) lets in-flight requests finish before a deregistering target is cut off. Setting it longer than the longest download stops connections from being dropped during scale-in."},{"text":"Enable cross-zone load balancing on the ALB.","correct":false,"why":"Cross-zone load balancing is always on for ALBs and only controls how traffic spreads across AZs. It doesn't affect health replacement or connection draining."},{"text":"Enable slow start mode on the target group with a 120-second duration.","correct":false,"why":"Slow start ramps up traffic to newly registered targets. It doesn't protect requests on targets being removed or trigger replacement of unhealthy ones."},{"text":"Change the Auto Scaling group termination policy to OldestInstance.","correct":false,"why":"Termination policies only choose which instance is removed during scale-in. They don't drain connections or detect hung applications."}],"takeaway":"Auto Scaling uses EC2 status checks unless you also turn on ELB health checks; deregistration delay is what drains in-flight requests.","trap":"EC2-only health checks miss application failures","services":["EC2 Auto Scaling","ELB"]},{"id":"resilience-011","domain":"resilience","topic":"Auto Scaling instance refresh","difficulty":"hard","scenario":"A company manages a 40-instance Auto Scaling group directly through the Auto Scaling API; it is not deployed with CloudFormation. Every month it publishes a new launch template version with a patched AMI. The rollout must keep at least 90% of capacity in service, and if a CloudWatch alarm on 5XX errors goes into ALARM during the rollout, the group must automatically go back to the previous launch template version.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Start an instance refresh with `MinHealthyPercentage` set to 90, auto rollback enabled, and an alarm specification that references the 5XX alarm.","correct":true,"why":"Instance refresh replaces instances in batches that respect the minimum healthy percentage. With AutoRollback and an AlarmSpecification, it automatically rolls back to the previous configuration if the alarm goes into ALARM during the refresh."},{"text":"Import the group into a CloudFormation stack and use an `AutoScalingRollingUpdate` update policy with `MinInstancesInService` set to 36.","correct":false,"why":"A rolling update policy only applies to groups that a CloudFormation stack manages. Importing an API-managed group into a stack and wiring up stack rollback triggers just to get this behavior adds overhead that instance refresh avoids."},{"text":"Write a Step Functions workflow that terminates 4 instances at a time, waits for replacements to pass health checks, and checks the alarm before each batch.","correct":false,"why":"This re-creates instance refresh by hand, including the rollback logic. It is much more code to own than the built-in feature."},{"text":"Set the new launch template version as default and let normal scale-in and scale-out events replace instances gradually over the month.","correct":false,"why":"Old instances may never be replaced in a predictable way, nothing enforces the 90% floor, and there is no automatic rollback on the alarm."}],"takeaway":"Instance refresh supports a minimum healthy percentage, checkpoints, and alarm-based auto rollback, which makes it the native way to roll out new AMIs.","trap":"Reaching for CloudFormation or custom orchestration when instance refresh does it natively","services":["EC2 Auto Scaling","CloudWatch"]},{"id":"resilience-012","domain":"resilience","topic":"Global Accelerator","difficulty":"hard","scenario":"A B2B company serves a write-heavy REST API (mostly POST and PUT requests) from ALBs in us-east-1 and eu-west-1. Enterprise customers' firewalls allow outbound traffic only to a fixed set of IP addresses. The company needs automatic failover to the healthy Region within about a minute, without depending on clients honoring DNS TTLs, and it wants to route users to the nearest healthy Region.","question":"Which solution meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Create an AWS Global Accelerator standard accelerator with an endpoint group in each Region that contains that Region's ALB, and give customers the accelerator's two static anycast IP addresses.","correct":true,"why":"Global Accelerator provides static anycast IPs and sends clients to the closest healthy endpoint group. Health-check-driven failover happens inside the AWS network without DNS changes, so client DNS caching doesn't matter."},{"text":"Put an Amazon CloudFront distribution in front of the API with an origin group that has the us-east-1 ALB as primary and the eu-west-1 ALB as secondary.","correct":false,"why":"CloudFront origin failover only happens for GET, HEAD, and OPTIONS requests, so failed POST and PUT calls would not be retried against the secondary. It also doesn't route to the nearest Region; the primary origin always comes first."},{"text":"Create Route 53 latency-based records with health checks for both ALBs and give customers the ALB IP addresses to allow-list.","correct":false,"why":"ALB IP addresses change over time and can't be allow-listed reliably. Failover also depends on DNS, so clients that cache records past the TTL keep hitting the failed Region."},{"text":"Put a Network Load Balancer with Elastic IP addresses in front of each ALB and use a Route 53 failover policy between the two NLBs.","correct":false,"why":"This produces static IPs per Region, but failover is still DNS-based and subject to client caching. It also gives active-passive failover rather than nearest-Region routing, with more components to run."}],"takeaway":"For static IPs plus fast multi-Region failover that doesn't depend on DNS, use Global Accelerator; CloudFront origin groups only fail over GET, HEAD, and OPTIONS.","trap":"CloudFront origin failover for non-idempotent methods","services":["Global Accelerator","CloudFront","Route 53","ELB"]},{"id":"resilience-013","domain":"resilience","topic":"AWS Backup","difficulty":"hard","scenario":"After a ransomware incident at a peer company, a healthcare organization that uses AWS Organizations wants to protect the backups of its production RDS databases and EBS volumes. Backups must survive even if attackers fully compromise the production account, including its root user. Recovery points must be impossible to delete before their 35-day retention ends, for anyone.","question":"Which combination of actions meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Enable cross-account backup in the Organizations management account and add a copy action to the backup plan that copies recovery points to a vault in a dedicated, isolated backup account.","correct":true,"why":"AWS Backup cross-account copy, which requires accounts in the same organization, puts copies outside the production account's blast radius. A compromised production root user can't delete recovery points in another account."},{"text":"Apply AWS Backup Vault Lock in compliance mode to the destination vault, with a minimum retention of 35 days.","correct":true,"why":"Once the compliance-mode grace period ends, the lock is immutable. No one, including the root user or AWS, can delete recovery points early or remove the lock."},{"text":"Apply AWS Backup Vault Lock in governance mode to the production vault.","correct":false,"why":"Governance mode can be changed or removed by users with sufficient IAM permissions, so a compromised root or admin in the production account could bypass it."},{"text":"Enable MFA Delete on the backup vault so deleting recovery points requires an MFA code.","correct":false,"why":"MFA Delete is an S3 bucket versioning feature. AWS Backup vaults have no MFA Delete setting."},{"text":"Use Amazon Data Lifecycle Manager to copy EBS snapshots to a second Region in the production account.","correct":false,"why":"The copies stay in the same compromised account, where the attacker can delete them. DLM also doesn't cover RDS and offers no immutability."}],"takeaway":"For ransomware-resistant backups, combine an isolated cross-account vault copy with Vault Lock in compliance mode.","trap":"Governance mode is not immutable","services":["AWS Backup","Organizations","RDS","EBS"]},{"id":"resilience-014","domain":"resilience","topic":"Elastic Disaster Recovery","difficulty":"medium","scenario":"A manufacturing company runs 60 critical Windows and Linux servers on VMware in its own data center. It wants to use AWS as its disaster recovery site with an RPO of seconds and an RTO of minutes. It also wants to minimize AWS spending while no disaster is happening, and it does not want to rewrite the applications.","question":"Which solution meets these requirements in the MOST cost-effective way?","qualifier":"MOST cost-effective","select":1,"options":[{"text":"Use AWS Elastic Disaster Recovery (AWS DRS) to continuously replicate the servers into a low-cost staging area subnet, and launch recovery instances only during a drill or disaster.","correct":true,"why":"AWS DRS does continuous block-level replication, which gives an RPO of seconds, onto lightweight replication servers and inexpensive staging volumes. Full-size recovery instances launch in minutes only when needed."},{"text":"Use AWS Backup for VMware to take hourly backups of the VMs and restore them to EC2 during a disaster.","correct":false,"why":"Periodic backups give an RPO of at least the backup interval, an hour here, and restoring 60 VMs takes much longer than minutes."},{"text":"Use AWS Application Migration Service (MGN) to replicate the servers and keep the launched test instances running in AWS as a standby.","correct":false,"why":"MGN is built for one-time lift-and-shift migrations, not ongoing DR with drills and failback. Keeping full-size instances running also defeats the cost goal."},{"text":"Build a warm standby in AWS by running scaled-down EC2 copies of every server and syncing data nightly with AWS DataSync.","correct":false,"why":"Nightly syncs give an RPO of hours, and always-on EC2 copies cost far more than DRS's staging area."}],"takeaway":"AWS Elastic Disaster Recovery gives an RPO of seconds and an RTO of minutes for on-premises or cloud servers while keeping a cheap staging area until failover.","trap":"Confusing MGN (migration) with DRS (disaster recovery)","services":["Elastic Disaster Recovery","AWS Backup","Application Migration Service"]},{"id":"resilience-015","domain":"resilience","topic":"SQS and Lambda decoupling","difficulty":"hard","scenario":"An order pipeline uses an SQS standard queue with a Lambda function as consumer. The function's timeout is 120 seconds, and the queue's visibility timeout is 30 seconds. The team sees orders processed two or three times, and a few malformed messages are retried forever. The function writes to an RDS database that can handle no more than 20 concurrent connections from this consumer.","question":"Which combination of changes resolves these issues while protecting the database? (Select THREE.)","qualifier":null,"select":3,"options":[{"text":"Set the queue's visibility timeout to at least 6 times the function timeout (for example, 720 seconds).","correct":true,"why":"Messages become visible again and are processed a second time when visibility expires before processing ends. AWS recommends a visibility timeout of at least 6 times the function timeout for Lambda event source mappings, to allow for retries and throttling."},{"text":"Configure a redrive policy that sends messages to a dead-letter queue after a `maxReceiveCount` of 5.","correct":true,"why":"A DLQ with a sensible maxReceiveCount moves poison messages out of the main queue after repeated failures instead of retrying them forever."},{"text":"Set maximum concurrency on the SQS event source mapping to 20.","correct":true,"why":"Maximum concurrency on the event source mapping caps how many concurrent invocations the SQS poller drives, without throttling. That keeps database connections within the limit."},{"text":"Set reserved concurrency on the function to 20 instead of using any event source mapping setting.","correct":false,"why":"With SQS, reserved concurrency alone lets the pollers scale beyond the reserved amount and get throttled. Throttled messages return to the queue and use up receive attempts, so valid messages can land in the DLQ early."},{"text":"Enable long polling by setting `ReceiveMessageWaitTimeSeconds` to 20 seconds.","correct":false,"why":"Lambda's SQS pollers already use long polling, and the setting only reduces empty receives. It does nothing about visibility expiring mid-processing or poison messages."},{"text":"Replace the queue with an SNS topic subscribed by the Lambda function so each order is delivered exactly once.","correct":false,"why":"SNS standard topics do not guarantee exactly-once delivery and do not buffer for a rate-limited consumer. This removes the decoupling the queue provides."}],"takeaway":"For SQS-to-Lambda: set visibility timeout to at least 6 times the function timeout, use a DLQ via maxReceiveCount, and cap concurrency with event source mapping maximum concurrency rather than reserved concurrency.","trap":"Using reserved concurrency to throttle an SQS consumer","services":["SQS","Lambda","RDS"]},{"id":"sdlc-001","domain":"sdlc","topic":"CodePipeline","difficulty":"hard","scenario":"A company runs AWS CodePipeline in a shared tooling account (111111111111). The pipeline uses AWS CodeBuild to package an AWS CloudFormation template and must deploy the stack into a production account (222222222222). The pipeline's S3 artifact bucket lives in the tooling account and objects are encrypted with the AWS managed key `aws/s3`. The deploy stage fails because the production account cannot read the input artifact.","question":"Which combination of steps will allow the pipeline to deploy to the production account? (Select THREE.)","qualifier":null,"select":3,"options":[{"text":"Create a customer managed AWS KMS key in the tooling account, set it as the encryption key of the pipeline's artifact store, and grant the production account's deployment roles `kms:Decrypt` and `kms:DescribeKey` in the key policy.","correct":true,"why":"Cross-account consumers can only decrypt artifacts if the key policy grants them access, and that is only possible with a customer managed key."},{"text":"Add a bucket policy to the artifact bucket that allows the production account's roles to call `s3:GetObject` and `s3:PutObject` on the bucket.","correct":true,"why":"Cross-account S3 access requires a resource-based bucket policy in addition to the caller's IAM permissions."},{"text":"Create an IAM role in the production account that trusts the tooling account, set it as the `roleArn` of the CloudFormation deploy action, and have the action pass a CloudFormation service role in the production account.","correct":true,"why":"CodePipeline assumes the action role in the target account to call CloudFormation there; the CloudFormation service role then provisions the resources with production-account permissions."},{"text":"Edit the key policy of the `aws/s3` AWS managed key to allow the production account to decrypt the artifacts.","correct":false,"why":"Key policies of AWS managed keys cannot be modified and cannot be used cross-account, which is exactly why a customer managed key is required."},{"text":"Enable S3 Cross-Region Replication from the artifact bucket to a bucket in the production account and point the deploy action at the replica.","correct":false,"why":"Pipeline actions read artifacts from the pipeline's configured artifact store, not an arbitrary replica, and replication does not solve the KMS decryption problem."},{"text":"Share the artifact bucket with the production account by using AWS Resource Access Manager (AWS RAM).","correct":false,"why":"General purpose S3 buckets are not shareable through AWS RAM; cross-account bucket access is granted with a bucket policy."}],"takeaway":"Cross-account CodePipeline needs three things: a customer managed KMS key shared via key policy, an artifact bucket policy, and an assumable role in the target account.","trap":"AWS managed KMS keys cannot be shared cross-account","services":["CodePipeline","KMS","S3","IAM","CloudFormation"]},{"id":"sdlc-002","domain":"sdlc","topic":"CodePipeline","difficulty":"hard","scenario":"A media company has an AWS CodePipeline pipeline in us-east-1 that builds an application and deploys it with an AWS CloudFormation action in us-east-1. The company now must deploy the same stack to eu-west-1 in the same account, in parallel with the us-east-1 deployment, right after the build stage. The company wants to keep a single pipeline as the only release definition.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Add a second CloudFormation deploy action to the existing deploy stage with its `region` field set to eu-west-1, and add an eu-west-1 artifact bucket (and its encryption key) to the pipeline's `artifactStores` configuration.","correct":true,"why":"CodePipeline supports cross-region actions natively: each action declares a region, and the pipeline copies artifacts to the artifact store configured for that region automatically."},{"text":"Create a second pipeline in eu-west-1 whose source is an S3 bucket populated by S3 Cross-Region Replication from the us-east-1 artifact bucket.","correct":false,"why":"This works but adds a second pipeline to maintain and makes the release definition no longer single, which increases overhead."},{"text":"Add an AWS Lambda invoke action that calls the CloudFormation API in eu-west-1 to create or update the stack.","correct":false,"why":"Custom code must handle create versus update, waiting, and error reporting, which a native cross-region CloudFormation action already does."},{"text":"Enable the cross-region read setting on the us-east-1 artifact store so that actions in any Region can read artifacts directly from it.","correct":false,"why":"No such setting exists; every Region that hosts an action needs its own artifact store bucket in that Region."}],"takeaway":"Cross-region CodePipeline actions just need a `region` on the action plus an artifact store bucket in every Region used.","trap":"Made-up feature / works but more overhead","services":["CodePipeline","CloudFormation","S3"]},{"id":"sdlc-003","domain":"sdlc","topic":"CodePipeline","difficulty":"hard","scenario":"A company stores its source code in a GitHub repository that is connected to AWS CodePipeline through an AWS CodeConnections connection. Developers push to many branches every day, and a separate pipeline already builds branch pushes. The production release pipeline must start only when a Git tag that matches `v*.*.*` is pushed, and it must never start on ordinary commits.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Use a pipeline of type V2 and configure a trigger on the source action with a push filter that includes tags matching `v*.*.*`.","correct":true,"why":"V2 pipelines support trigger filters on Git tags, branches, and file paths for CodeConnections sources, so the pipeline starts only on matching tag pushes."},{"text":"Create an Amazon EventBridge rule that matches tag push events emitted by the GitHub connection and starts the pipeline.","correct":false,"why":"GitHub pushes through CodeConnections are not delivered to EventBridge as tag events; EventBridge source events like this exist for CodeCommit, not GitHub."},{"text":"Keep a V1 pipeline and add a first-stage AWS Lambda invoke action that inspects the commit and stops the execution when it is not a tag push.","correct":false,"why":"This works but runs the pipeline on every push and requires custom code, so it has more overhead and cost than a native trigger filter."},{"text":"Set the `BranchName` of the source action to `refs/tags/v*` so the action only detects tag references.","correct":false,"why":"The `BranchName` setting takes a single branch name and does not support glob patterns or tag references; tag filtering requires V2 triggers."}],"takeaway":"Filtering pipeline starts by Git tag, branch glob, or file path requires a V2 pipeline trigger.","trap":"V1 pipelines cannot filter on tags","services":["CodePipeline","CodeConnections","EventBridge"]},{"id":"sdlc-004","domain":"sdlc","topic":"CodeBuild","difficulty":"medium","scenario":"An AWS CodeBuild project installs dependencies from a private npm registry. The registry token is currently stored as a plaintext environment variable in the CodeBuild project, so anyone with read access to the project can see it. The security team has stored the token in AWS Secrets Manager with automatic rotation and requires that the token never appears in the project configuration or in build logs.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Reference the secret in the buildspec under `env` > `secrets-manager` (for example `NPM_TOKEN: prod/npm:token`) and grant the CodeBuild service role `secretsmanager:GetSecretValue` on the secret.","correct":true,"why":"CodeBuild resolves `secrets-manager` references at build start, always gets the current rotated value, and masks the value in build logs."},{"text":"Change the environment variable to type `PARAMETER_STORE` and point it at a `String` parameter that contains the token.","correct":false,"why":"A `String` parameter is not encrypted and would duplicate the secret outside Secrets Manager, so rotation would no longer flow through."},{"text":"Store the token in an encrypted S3 object and download and decrypt it with the AWS CLI in the `pre_build` phase.","correct":false,"why":"This works but adds custom handling, a second copy of the secret, and no automatic masking in logs, which is more overhead and less secure."},{"text":"Add the token to the buildspec `env` > `exported-variables` section so it is only available to later pipeline actions.","correct":false,"why":"Exported variables are meant to be shared and are visible in the pipeline execution history, which exposes the token."}],"takeaway":"Use buildspec `env.secrets-manager` / `env.parameter-store` for secrets; CodeBuild fetches them at runtime and masks them in logs.","trap":"Secret visible in exported variables or plaintext env vars","services":["CodeBuild","Secrets Manager","Systems Manager"]},{"id":"sdlc-005","domain":"sdlc","topic":"CodeBuild","difficulty":"hard","scenario":"An AWS CodeBuild project runs integration tests against an Amazon RDS database in private subnets of a VPC. The tests also download packages from the public internet. A DevOps engineer configured the project's VPC settings with two public subnets whose route tables point to an internet gateway, and a security group that the database allows. The builds can now reach the database but time out when downloading packages.","question":"Which change will resolve the issue in the MOST secure way?","qualifier":"MOST secure","select":1,"options":[{"text":"Configure the project to use private subnets whose route tables send `0.0.0.0/0` to a NAT gateway in a public subnet, keeping the existing security group.","correct":true,"why":"CodeBuild network interfaces in a VPC never receive public IP addresses, so internet access must go through a NAT gateway from private subnets."},{"text":"Enable auto-assign public IPv4 addresses on the two public subnets used by the project.","correct":false,"why":"CodeBuild-created ENIs do not get public IPs even when the subnet setting is enabled, so the builds still cannot reach the internet."},{"text":"Allocate an Elastic IP address and associate it with the network interface that CodeBuild creates for each build.","correct":false,"why":"The ENIs are created and deleted by CodeBuild per build and are not meant to be managed; this cannot be done reliably and is not supported."},{"text":"Remove the VPC configuration from the project and make the RDS database publicly accessible with a security group rule for CodeBuild IP ranges.","correct":false,"why":"Exposing the database publicly is far less secure than keeping it private and routing outbound traffic through a NAT gateway."}],"takeaway":"CodeBuild in a VPC must use private subnets with a NAT gateway for internet access; public subnets do not work.","trap":"Public subnets do not give CodeBuild internet access","services":["CodeBuild","VPC","RDS"]},{"id":"sdlc-006","domain":"sdlc","topic":"CodeBuild","difficulty":"medium","scenario":"A team builds a Java application with Maven in AWS CodeBuild. Each build spends about 6 minutes downloading the same dependencies into `/root/.m2`. Builds run only three or four times a day, at unpredictable times. The team wants to cut build time without maintaining additional infrastructure.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Enable Amazon S3 caching on the project and add `cache: paths: - '/root/.m2/**/*'` to the buildspec.","correct":true,"why":"An S3 cache is stored durably and restored on any build host, so it helps even when builds are hours apart."},{"text":"Enable local caching with the `LOCAL_CUSTOM_CACHE` mode and list `/root/.m2/**/*` in the buildspec cache paths.","correct":false,"why":"Local caching is best-effort and only reused when a later build lands on the same host shortly after, so infrequent builds rarely benefit."},{"text":"Build a custom build image that already contains the dependencies, push it to Amazon ECR, and rebuild the image whenever dependencies change.","correct":false,"why":"This works but adds an image pipeline to maintain whenever dependencies change, which is more overhead than a cache setting."},{"text":"Switch the project to a larger compute type so the dependency download completes faster.","correct":false,"why":"The bottleneck is repeated network downloads, not CPU or memory, and larger compute costs more without removing the downloads."}],"takeaway":"Use S3 caching for infrequent builds; local caching only helps builds that run close together on the same host.","trap":"Local cache is best-effort","services":["CodeBuild","S3"]},{"id":"sdlc-007","domain":"sdlc","topic":"CodeBuild","difficulty":"medium","scenario":"A Python team runs `pytest` in AWS CodeBuild. Managers want to see pass/fail counts per test case and code coverage trends across builds in the AWS console, without operating any additional reporting tool. The tests already write a JUnit XML file and a Cobertura XML coverage file to the `reports/` directory.","question":"What should a DevOps engineer do to meet these requirements?","qualifier":null,"select":1,"options":[{"text":"Add a `reports` section to the buildspec that defines one report group with `file-format: JUNITXML` and one with `file-format: COBERTURAXML`, both with `base-directory: reports`, and allow the service role to create and update report groups and reports.","correct":true,"why":"CodeBuild test and coverage reports are defined in the buildspec `reports` section and appear in report groups with history and trends in the console."},{"text":"Upload the XML files as build artifacts to S3 and enable the S3 test report view on the bucket.","correct":false,"why":"S3 has no test report view; the files would just be objects without any parsing or trends."},{"text":"Stream the XML files to Amazon CloudWatch Logs and build CloudWatch Logs Insights queries for pass/fail counts.","correct":false,"why":"This requires custom parsing and dashboards, which is additional tooling that CodeBuild reports provide natively."},{"text":"Associate the repository with Amazon CodeGuru Reviewer to display test results and coverage.","correct":false,"why":"CodeGuru Reviewer analyzes code for defects; it does not ingest test results or coverage files."}],"takeaway":"CodeBuild report groups (buildspec `reports`) show test results (JUnit, NUnit, TestNG, Cucumber...) and coverage (JaCoCo, Cobertura, Clover, SimpleCov).","trap":"Service that exists but does a different job","services":["CodeBuild"]},{"id":"sdlc-008","domain":"sdlc","topic":"SAM","difficulty":"hard","scenario":"A company deploys an AWS Lambda function with an AWS SAM template. For every release, 10% of traffic must go to the new version for 10 minutes and then the remaining 90% must shift at once. A validation function must run integration checks before any production traffic reaches the new version, and the deployment must roll back automatically if a CloudWatch alarm on function errors enters the ALARM state.","question":"Which SAM configuration meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Set `AutoPublishAlias: live` and a `DeploymentPreference` with `Type: Canary10Percent10Minutes`, `Alarms` listing the error alarm, and `Hooks: PreTraffic` referencing the validation function.","correct":true,"why":"SAM publishes a version to the alias and creates a CodeDeploy deployment; canary shifts 10% then the rest, PreTraffic maps to BeforeAllowTraffic, and alarms trigger automatic rollback."},{"text":"Set `AutoPublishAlias: live` and a `DeploymentPreference` with `Type: Linear10PercentEvery10Minutes`, `Alarms` listing the error alarm, and `Hooks: PreTraffic` referencing the validation function.","correct":false,"why":"Linear shifts 10% every 10 minutes in ten increments (about 100 minutes), not 10% followed by the remaining 90% at once."},{"text":"Set `AutoPublishAlias: live` and a `DeploymentPreference` with `Type: Canary10Percent10Minutes`, `Alarms` listing the error alarm, and `Hooks: PostTraffic` referencing the validation function.","correct":false,"why":"PostTraffic (AfterAllowTraffic) runs after all traffic has shifted, so the checks would not run before production traffic reaches the new version."},{"text":"Omit `AutoPublishAlias` and add a `DeploymentPreference` with `Type: Canary10Percent10Minutes`, `Alarms`, and `Hooks: PreTraffic`; SAM shifts traffic on `$LATEST`.","correct":false,"why":"Gradual deployments require an alias and published versions; traffic cannot be shifted on `$LATEST`."}],"takeaway":"SAM gradual deploys = AutoPublishAlias + DeploymentPreference (Canary/Linear/AllAtOnce) + Alarms + PreTraffic/PostTraffic hooks.","trap":"Canary vs linear confusion / wrong hook","services":["SAM","Lambda","CodeDeploy","CloudWatch"]},{"id":"sdlc-009","domain":"sdlc","topic":"CodeDeploy","difficulty":"hard","scenario":"A company runs an Amazon ECS service on AWS Fargate behind an Application Load Balancer and deploys it with AWS CodeDeploy blue/green deployments. The company wants automated integration tests to run against the replacement (green) task set before any production traffic is shifted to it. If the tests fail, the deployment must roll back automatically.","question":"Which combination of steps meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Add a test listener (for example on port 8443) to the ALB and specify it as the test traffic route in the deployment group's load balancer configuration.","correct":true,"why":"The test listener routes to the green target group before production traffic shifts, giving the tests an endpoint for the new task set."},{"text":"Create an AWS Lambda function that runs the tests against the test listener and reports `Failed` or `Succeeded` with `PutLifecycleEventHookExecutionStatus`, and reference it in the `AfterAllowTestTraffic` hook of the AppSpec file.","correct":true,"why":"ECS AppSpec hooks are Lambda functions; `AfterAllowTestTraffic` runs once test traffic reaches green, and a `Failed` status stops and rolls back the deployment."},{"text":"Add a shell script under the `ValidateService` hook in the AppSpec file that calls the new tasks with `curl`.","correct":false,"why":"`ValidateService` and script-based hooks exist only for EC2/on-premises deployments; ECS hooks invoke Lambda functions."},{"text":"Use the `CodeDeployDefault.ECSCanary10Percent5Minutes` configuration with a CloudWatch alarm on 5XX errors.","correct":false,"why":"A canary sends real production traffic to green before any tests run, which violates the requirement."},{"text":"Add the tests to an `ApplicationStop` hook so they run before the original task set is stopped.","correct":false,"why":"`ApplicationStop` is an EC2/on-premises lifecycle event and does not exist for ECS deployments."}],"takeaway":"ECS blue/green: test listener + Lambda in AfterAllowTestTraffic (or BeforeAllowTraffic) to gate production traffic.","trap":"EC2 lifecycle hooks used on ECS","services":["CodeDeploy","ECS","Fargate","Elastic Load Balancing","Lambda"]},{"id":"sdlc-010","domain":"sdlc","topic":"CodeDeploy","difficulty":"hard","scenario":"A company uses AWS CodeDeploy in-place deployments to a fleet of Amazon EC2 instances. A recent revision shipped an `ApplicationStop` script that hangs. The team fixed the script in a new revision, but every new deployment fails at the `ApplicationStop` lifecycle event with a `ScriptTimedOut` error on all instances.","question":"What should a DevOps engineer do to deploy the fixed revision with the FEWEST changes?","qualifier":"FEWEST changes","select":1,"options":[{"text":"Redeploy the fixed revision with the option to not fail the deployment when the `ApplicationStop` lifecycle event fails (`--ignore-application-stop-failures`).","correct":true,"why":"`ApplicationStop` runs the script from the last successfully deployed revision, so the broken script keeps running until that event's failure is ignored once."},{"text":"Increase the `timeout` value for the `ApplicationStop` hook in the AppSpec file of the fixed revision and redeploy.","correct":false,"why":"The `ApplicationStop` event uses the AppSpec file and scripts of the previously deployed revision, so changes in the new revision have no effect on it."},{"text":"Restart the CodeDeploy agent on all instances and redeploy the fixed revision.","correct":false,"why":"Restarting the agent does not change which `ApplicationStop` script runs; the same hanging script runs again."},{"text":"Change the deployment configuration from `CodeDeployDefault.OneAtATime` to `CodeDeployDefault.AllAtOnce` and redeploy.","correct":false,"why":"The deployment configuration controls how many instances deploy at once, not which scripts run, so every instance still times out."}],"takeaway":"ApplicationStop runs the previous revision's script; fix a broken one by deploying with ignore-application-stop-failures.","trap":"ApplicationStop uses the OLD revision","services":["CodeDeploy","EC2"]},{"id":"sdlc-011","domain":"sdlc","topic":"CodeDeploy","difficulty":"medium","scenario":"A company deploys an application to 10 Amazon EC2 instances with AWS CodeDeploy in-place deployments. Load tests show the application needs at least 8 instances serving traffic to handle peak load, and deployments can happen at peak time. The company wants deployments to finish as quickly as possible.","question":"Which deployment configuration meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Create a custom deployment configuration with a minimum healthy hosts value of 80% (`FLEET_PERCENT`).","correct":true,"why":"With 80% minimum healthy hosts, CodeDeploy updates two instances at a time while keeping 8 healthy, which is the fastest option that satisfies the capacity floor."},{"text":"Use `CodeDeployDefault.OneAtATime`.","correct":false,"why":"It keeps 9 instances healthy and meets the capacity floor, but deploying one instance at a time is slower than necessary."},{"text":"Use `CodeDeployDefault.HalfAtATime`.","correct":false,"why":"HalfAtATime keeps only 50% (5 instances) healthy, below the 8-instance requirement."},{"text":"Use `CodeDeployDefault.AllAtOnce`.","correct":false,"why":"AllAtOnce can take every instance out of service at the same time, leaving no capacity during deployment."}],"takeaway":"Minimum healthy hosts sets deployment speed vs capacity; create a custom config when the predefined ones are too slow or too aggressive.","trap":"Works but not the fastest","services":["CodeDeploy","EC2"]},{"id":"sdlc-012","domain":"sdlc","topic":"CodeDeploy","difficulty":"hard","scenario":"A company uses AWS CodeDeploy to deploy to an Auto Scaling group of Amazon EC2 instances. A CloudWatch alarm watches the Application Load Balancer's HTTP 5XX count. The company wants CodeDeploy to stop a deployment automatically and return to the last known good revision when this alarm fires during the deployment, and also when a deployment fails for any other reason.","question":"Which combination of steps meets these requirements with the LEAST operational overhead? (Select TWO.)","qualifier":"LEAST operational overhead","select":2,"options":[{"text":"Add the CloudWatch alarm to the alarm configuration of the CodeDeploy deployment group.","correct":true,"why":"CodeDeploy monitors alarms attached to the deployment group and stops the deployment when one goes into ALARM."},{"text":"Enable automatic rollback on the deployment group for both 'when a deployment fails' and 'when alarm thresholds are met'.","correct":true,"why":"With these settings CodeDeploy automatically redeploys the last known good revision as a new deployment after a failure or alarm stop."},{"text":"Create an Amazon EventBridge rule for the alarm state change that invokes an AWS Lambda function calling `StopDeployment` with `autoRollbackEnabled` set to true.","correct":false,"why":"This works but adds custom code and infrastructure for behavior CodeDeploy provides natively in the deployment group."},{"text":"Configure CloudFormation rollback triggers with the alarm on the deployment group resource.","correct":false,"why":"Rollback triggers act on CloudFormation stack operations, not on CodeDeploy deployments."},{"text":"Add a `ValidateService` hook script that polls the alarm and exits with a non-zero code while it is in ALARM.","correct":false,"why":"It only checks at one lifecycle point per instance and needs custom scripting; the native alarm configuration watches the whole deployment."}],"takeaway":"CodeDeploy rollback = alarms on the deployment group + auto-rollback settings; a rollback is a new deployment of the last good revision.","trap":"Works but more overhead","services":["CodeDeploy","CloudWatch","EC2 Auto Scaling"]},{"id":"sdlc-013","domain":"sdlc","topic":"CodeArtifact","difficulty":"hard","scenario":"A company builds Node.js applications in AWS CodeBuild projects that run in private VPC subnets with no internet access. The builds must install public packages from the npmjs registry and publish internal packages, and every public package version used must be cached inside AWS so builds keep working if the public registry is unavailable. The VPC must not get a route to the internet.","question":"Which combination of steps meets these requirements? (Select THREE.)","qualifier":null,"select":3,"options":[{"text":"Create an AWS CodeArtifact domain with an internal repository whose upstream repository has an external connection to `public:npmjs`, and run `aws codeartifact login --tool npm` in the buildspec.","correct":true,"why":"Packages pulled through the upstream are fetched from npmjs by CodeArtifact and retained in the repository, and internal packages can be published to the same repository."},{"text":"Create interface VPC endpoints for `com.amazonaws.<region>.codeartifact.api` and `com.amazonaws.<region>.codeartifact.repositories`.","correct":true,"why":"The `api` endpoint is used for operations like `GetAuthorizationToken`, and the `repositories` endpoint serves package manager traffic."},{"text":"Create an Amazon S3 gateway VPC endpoint for the Region.","correct":true,"why":"CodeArtifact stores package assets in S3, so private builds need S3 access to download them."},{"text":"Add a NAT gateway so CodeBuild can reach npmjs when a package is not yet cached.","correct":false,"why":"This gives the VPC a route to the internet, which is not allowed, and is unnecessary because CodeArtifact fetches public packages itself."},{"text":"Store the npm packages in an Amazon ECR repository and point npm at the ECR registry URL.","correct":false,"why":"ECR is a container image and OCI artifact registry; it does not implement the npm registry protocol."},{"text":"Configure the npm client to use the CodeArtifact public npm mirror endpoint, which needs no repository.","correct":false,"why":"CodeArtifact has no repository-less public mirror endpoint; public packages are reached through a repository with an external connection."}],"takeaway":"CodeArtifact without internet: external connection on an upstream repo + codeartifact.api and codeartifact.repositories endpoints + S3 gateway endpoint.","trap":"Forgetting the S3 gateway endpoint","services":["CodeArtifact","CodeBuild","VPC","S3"]},{"id":"sdlc-014","domain":"sdlc","topic":"ECR","difficulty":"hard","scenario":"A company keeps all container images in Amazon ECR private repositories in a central shared-services account. Amazon ECS tasks in several workload accounts must pull images from these repositories. The security team requires least-privilege access, no copies of images in the workload accounts, and no public exposure.","question":"Which solution meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Add a repository policy in the central account that allows `ecr:BatchGetImage`, `ecr:GetDownloadUrlForLayer`, and `ecr:BatchCheckLayerAvailability` for the workload accounts' task execution roles, and allow those roles `ecr:GetAuthorizationToken` plus the same pull actions on the central repositories in their IAM policies.","correct":true,"why":"Cross-account pulls need both the resource-based repository policy and the identity-based policy on the task execution role; `GetAuthorizationToken` is a registry-level action granted in IAM."},{"text":"Configure ECR cross-account replication from the central registry to each workload account's registry.","correct":false,"why":"Replication creates copies of the images in each workload account, which the requirement forbids."},{"text":"Share the ECR repositories with the workload accounts by using AWS Resource Access Manager (AWS RAM).","correct":false,"why":"ECR repositories are not shareable through AWS RAM; cross-account access is granted with repository policies."},{"text":"Grant only `ecr:GetAuthorizationToken` to the workload accounts in the repository policy, because the token authorizes all subsequent pulls.","correct":false,"why":"The authorization token only authenticates the Docker client; the image and layer pull actions must still be allowed explicitly."}],"takeaway":"Cross-account ECR pull = repository policy (pull actions) + IAM policy on the puller (GetAuthorizationToken + pull actions).","trap":"RAM does not share ECR repos","services":["ECR","ECS","IAM"]},{"id":"sdlc-015","domain":"sdlc","topic":"ECR","difficulty":"hard","scenario":"A company stores hundreds of container images in Amazon ECR. The security team needs vulnerability scanning of both operating system packages and application language packages (such as Python and Java libraries). Images must be rescanned automatically when new CVEs are published, not only when pushed, and the team must be notified by email of any CRITICAL finding.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Turn on ECR enhanced scanning (Amazon Inspector) for the registry with continuous scanning, and create an Amazon EventBridge rule for `aws.inspector2` finding events with severity CRITICAL that targets an Amazon SNS topic with email subscriptions.","correct":true,"why":"Enhanced scanning uses Amazon Inspector to scan OS and language packages and rescans continuously as new CVEs appear; findings are emitted to EventBridge."},{"text":"Turn on basic scanning with scan on push and create an EventBridge rule for ECR image scan events that targets an SNS topic.","correct":false,"why":"Basic scanning focuses on OS packages and only scans on push or on demand, so it neither covers language packages nor rescans automatically."},{"text":"Run a nightly AWS CodeBuild job that pulls every image, scans it with an open-source scanner, and publishes CRITICAL results to SNS.","correct":false,"why":"This could work but requires building and maintaining a custom scanning pipeline, which is much more overhead than enhanced scanning."},{"text":"Enable Amazon GuardDuty ECS Runtime Monitoring and subscribe the team to GuardDuty findings.","correct":false,"why":"GuardDuty runtime monitoring detects threats in running workloads; it does not scan images in ECR for package vulnerabilities."}],"takeaway":"ECR enhanced scanning = Inspector, OS + language packages, continuous rescans; basic scanning = OS packages, on push/manual.","trap":"Basic vs enhanced scanning","services":["ECR","Inspector","EventBridge","SNS"]},{"id":"sdlc-016","domain":"sdlc","topic":"Elastic Beanstalk","difficulty":"hard","scenario":"A company runs a web application on an AWS Elastic Beanstalk load-balanced environment with an Application Load Balancer. For each release, the company wants to deploy the new version to a fresh set of instances so a bad release never touches the running instances, keep full capacity throughout, and send 10% of client traffic to the new version for 15 minutes before shifting all traffic. The environment URL must not change.","question":"Which deployment policy meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Traffic splitting with a 10% traffic split and a 15-minute evaluation time.","correct":true,"why":"Traffic splitting launches new instances in a temporary Auto Scaling group, routes the chosen percentage of traffic through the same load balancer for the evaluation period, then moves all traffic and terminates the old instances."},{"text":"Immutable.","correct":false,"why":"Immutable uses fresh instances and full capacity, but it does not send a configurable percentage of traffic for an evaluation period."},{"text":"Rolling with additional batch.","correct":false,"why":"It keeps full capacity, but after the extra batch it deploys onto existing instances in place, so a bad release can affect running instances."},{"text":"Blue/green deployment by cloning the environment and swapping environment URLs.","correct":false,"why":"A CNAME swap moves all traffic at once (subject to DNS caching) and involves a second environment rather than a percentage split within the same environment."}],"takeaway":"Need a percentage canary inside the same Beanstalk environment on new instances? Traffic splitting.","trap":"Immutable vs traffic splitting","services":["Elastic Beanstalk","Elastic Load Balancing","EC2 Auto Scaling"]},{"id":"sdlc-017","domain":"sdlc","topic":"Elastic Beanstalk","difficulty":"hard","scenario":"A company runs a Node.js application on an AWS Elastic Beanstalk environment on an Amazon Linux 2 platform branch. An Amazon RDS DB instance was created as part of the environment configuration. The company must move to an Amazon Linux 2023 platform branch with the ability to roll back instantly, and the production data in the database must be preserved and remain in use by the new version.","question":"Which combination of steps meets these requirements? (Select TWO.)","qualifier":null,"select":2,"options":[{"text":"Decouple the RDS DB instance from the environment (with the database deletion policy set to retain) and configure the application to read the connection details from environment properties or AWS Secrets Manager.","correct":true,"why":"A database coupled to an environment shares its lifecycle; decoupling keeps the DB independent so both the old and new environments can use it."},{"text":"Create a new environment on the Amazon Linux 2023 platform branch pointing at the same database, test it, and then use Swap environment URLs; swap back to roll back.","correct":true,"why":"Changing platform branches is done with a blue/green deployment, and the CNAME swap is reversible for fast rollback."},{"text":"Clone the existing environment with the latest platform version and swap environment URLs.","correct":false,"why":"Cloning copies the coupled database configuration and creates a new, empty DB instance, and a clone stays on the same platform branch."},{"text":"Run a rolling with additional batch deployment and select the Amazon Linux 2023 platform in the same environment.","correct":false,"why":"Deployment policies deploy application versions; moving to a different platform branch should be done in a new environment, and this offers no instant rollback."},{"text":"Run an immutable deployment, which keeps the RDS DB instance and replaces only the EC2 instances.","correct":false,"why":"Immutable deploys a new application version on new instances in the same environment; it does not migrate platform branches or provide an instant swap back."}],"takeaway":"Platform branch changes = blue/green with Swap environment URLs; decouple RDS from the environment first so the data survives.","trap":"Cloning an environment clones its coupled database","services":["Elastic Beanstalk","RDS","Secrets Manager"]},{"id":"sdlc-018","domain":"sdlc","topic":"CodePipeline","difficulty":"hard","scenario":"A company's AWS CodePipeline pipeline deploys an AWS CloudFormation stack to a staging environment, runs automated integration tests in AWS CodeBuild, and then waits at a manual approval action before deploying to production. The staging stack's URL changes with every deployment and is exposed as a stack output named `WebsiteURL`. Approvers must receive the current staging URL in the approval request so they can review the site before approving.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Assign a variable namespace (for example `StagingVars`) to the staging CloudFormation action and set the approval action's URL for review to `#{StagingVars.WebsiteURL}`, with an Amazon SNS topic configured on the approval action.","correct":true,"why":"CloudFormation deploy actions expose stack outputs as action variables, and the approval action can reference them in its review URL and custom data."},{"text":"Add an AWS Lambda invoke action that reads the stack outputs and emails the URL to the approvers through Amazon SES before the approval action.","correct":false,"why":"This works but adds custom code and email infrastructure for something pipeline variables provide natively."},{"text":"Store the URL in AWS Systems Manager Parameter Store and reference it in the approval action with `{{resolve:ssm:/staging/url}}`.","correct":false,"why":"The `{{resolve:...}}` dynamic reference syntax is a CloudFormation template feature; pipeline action configuration uses `#{namespace.variable}`."},{"text":"Add a CodeBuild action that runs `aws cloudformation describe-stacks` and exports the URL with `exported-variables`, then reference that variable in the approval action.","correct":false,"why":"This works but adds an extra build action, runtime, and cost when the CloudFormation action already exposes the output as a variable."}],"takeaway":"CloudFormation action outputs become pipeline variables via a namespace; reference them with #{Namespace.Output}.","trap":"Works but more overhead","services":["CodePipeline","CloudFormation","CodeBuild","SNS"]},{"id":"security-001","domain":"security","topic":"IAM permission boundaries","difficulty":"hard","scenario":"A software company wants its application developers to create IAM roles for their own Lambda functions without opening a ticket with the cloud team. The security team requires that no role a developer creates can ever have more permissions than a predefined `DevWorkloadBoundary` managed policy allows, even if the developer attaches `AdministratorAccess` to it. Developers must not be able to get around the control.","question":"Which solution meets these requirements while following the principle of LEAST privilege?","qualifier":"LEAST privilege","select":1,"options":[{"text":"Grant developers `iam:CreateRole`, `iam:AttachRolePolicy`, and `iam:PutRolePolicy` only when the condition `iam:PermissionsBoundary` equals the `DevWorkloadBoundary` ARN. Explicitly deny `iam:DeleteRolePermissionsBoundary`, changes to the boundary policy itself, and `iam:PutRolePermissionsBoundary` with any other policy.","correct":true,"why":"A permissions boundary caps the effective permissions of a role at what both the identity policy and the boundary allow. The `iam:PermissionsBoundary` condition forces every new role to carry the boundary, and the explicit denies stop developers from removing or loosening it."},{"text":"Attach an SCP to the developers' account that denies every action not listed in `DevWorkloadBoundary`.","correct":false,"why":"An SCP limits every principal in the account, including the cloud team and pipelines, not just roles developers create. It also does nothing to stop developers from creating roles."},{"text":"Require developers to pass `DevWorkloadBoundary` as a session policy when they assume their developer role.","correct":false,"why":"A session policy only limits the developer's own session. It has no effect on the permissions of roles the developer creates, which Lambda later assumes on its own."},{"text":"Use IAM Access Analyzer custom policy checks in a nightly job to find roles that grant more than `DevWorkloadBoundary` and delete them.","correct":false,"why":"This only detects problems after the fact, so over-privileged roles exist until the job runs. The requirement is that roles can never exceed the boundary."}],"takeaway":"To safely delegate role creation, use a permissions boundary, require it with the iam:PermissionsBoundary condition, and deny removing or editing it.","trap":"Session policies/SCPs instead of permissions boundaries","services":["IAM"]},{"id":"security-002","domain":"security","topic":"Organizations SCPs","difficulty":"hard","scenario":"A company's organization root has the default `FullAWSAccess` SCP. The `Workloads` OU had `FullAWSAccess` replaced with an allow-list SCP that allows only `ec2:*`, `s3:*`, `cloudwatch:*`, and `logs:*`. Account `111122223333` in that OU has both `FullAWSAccess` and a custom SCP that allows `lambda:*`. An administrator in the account who has the `AdministratorAccess` IAM policy gets an access denied error when creating a Lambda function.","question":"What is the cause, and how should the issue be resolved?","qualifier":null,"select":1,"options":[{"text":"An action must be allowed by SCPs at every level from the root down to the account. `lambda:*` is not allowed by the `Workloads` OU SCP, so add `lambda:*` to that OU's allow-list SCP.","correct":true,"why":"Effective SCP permissions are the intersection across the root, each OU in the path, and the account. An allow attached lower down cannot add back an action that a parent OU's allow-list leaves out."},{"text":"SCPs never grant permissions, so add an IAM policy with `lambda:CreateFunction` to the administrator.","correct":false,"why":"It's true that SCPs don't grant permissions, but `AdministratorAccess` already allows Lambda. What blocks the call is the OU's SCP filter, which no IAM policy can override."},{"text":"SCP allows attached directly to an account override the SCPs inherited from its parent OU, so the account-level `lambda:*` allow is the one that applies. The new account SCP simply hasn't propagated yet; wait up to 24 hours and try again.","correct":false,"why":"There is no override between levels; every level has to allow the action. SCP changes also take effect within minutes, not hours."},{"text":"Move the Lambda permission into a new SCP attached to the organization root.","correct":false,"why":"The root already allows everything through `FullAWSAccess`. The OU allow-list still filters out Lambda for every account beneath it."}],"takeaway":"SCP permissions are the intersection along the entire path from root to OU to account. An allow lower down cannot restore what a parent filters out.","trap":"SCP inheritance misconception","services":["Organizations","IAM"]},{"id":"security-003","domain":"security","topic":"IAM Identity Center ABAC","difficulty":"hard","scenario":"A consulting firm uses IAM Identity Center with Okta as its external identity provider. 120 project teams share several AWS accounts, and each team's resources carry a `project` tag. Each consultant must manage EC2 instances and Secrets Manager secrets only for the project in their Okta profile. Consultants move between projects every few weeks, and the cloud team wants to avoid per-project changes in AWS.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Enable attributes for access control in IAM Identity Center, mapping the Okta `project` attribute (passed in the SAML assertion or through SCIM) to a session tag. Create one permission set whose policy allows actions only when `aws:ResourceTag/project` equals `${aws:PrincipalTag/project}`.","correct":true,"why":"This is ABAC: Identity Center passes the user's attribute as a principal tag on the session, so one permission set works for every project. Moving a consultant only requires changing the attribute in Okta."},{"text":"Create one permission set per project with resource ARNs hard-coded, and assign consultants to the matching permission set when they change projects.","correct":false,"why":"This is role-based access with 120 permission sets to maintain and reassignments every time someone moves. That is the overhead ABAC is meant to remove."},{"text":"Create an IAM OIDC identity provider for Okta in each account and have consultants use `AssumeRoleWithWebIdentity` with a project-specific role.","correct":false,"why":"This bypasses Identity Center, requires per-account providers and per-project roles, and uses web identity federation meant for apps rather than workforce console access."},{"text":"Use a permission set with a permissions boundary that lists every project's resources, and use SCPs to deny access to other projects' resources.","correct":false,"why":"Boundaries and SCPs can't tell which project a user belongs to, and listing resources means constant updates. Isolation per user needs principal tags."}],"takeaway":"ABAC with Identity Center: pass IdP attributes as session tags and compare aws:PrincipalTag to aws:ResourceTag in a single permission set.","trap":"Role-per-project explosion instead of ABAC","services":["IAM Identity Center","IAM"]},{"id":"security-004","domain":"security","topic":"IAM Access Analyzer","difficulty":"hard","scenario":"After an audit, a bank must reduce standing privileges across 60 accounts in AWS Organizations. The security team needs a continuously updated, centralized view of IAM roles and users that haven't been used recently, and of permissions that roles have but never use. For roles that are still in use, the team wants a starting least-privilege policy based on what the role actually did over the past 90 days.","question":"Which combination of actions meets these requirements with the LEAST operational overhead? (Select TWO.)","qualifier":"LEAST operational overhead","select":2,"options":[{"text":"Create an IAM Access Analyzer unused access analyzer with the organization as the zone of trust, from the delegated administrator account, with a tracking period of 90 days.","correct":true,"why":"Unused access analyzers continuously report unused roles, unused access keys and passwords, and unused service- and action-level permissions for every account in the organization, from one place."},{"text":"Use IAM Access Analyzer policy generation for the active roles, pointing it at the organization CloudTrail trail for the 90-day window.","correct":true,"why":"Policy generation reads the role's CloudTrail activity and produces a policy limited to the services and actions actually used, which gives a least-privilege starting point."},{"text":"Download the IAM credential report from each account every week and combine the reports in Amazon Athena.","correct":false,"why":"Credential reports only cover IAM users, not roles or unused permissions. Collecting them from 60 accounts every week is manual overhead."},{"text":"Deploy the `iam-user-unused-credentials-check` AWS Config rule through an organization conformance pack.","correct":false,"why":"That rule only checks IAM user passwords and keys. It ignores roles and can't find unused permissions inside policies."},{"text":"Run IAM Access Analyzer `CheckNoNewAccess` custom policy checks in the CI/CD pipeline for every policy change.","correct":false,"why":"Custom policy checks validate policy changes before deployment, which is useful as a guardrail. They don't find access that is already granted but unused."}],"takeaway":"Access Analyzer covers three jobs: external access findings, unused access findings (org-wide), and policy generation from CloudTrail for least privilege.","trap":"Credential report covers users only","services":["IAM Access Analyzer","IAM","CloudTrail","Organizations"]},{"id":"security-005","domain":"security","topic":"Resource control policies","difficulty":"hard","scenario":"A pharmaceutical company has hundreds of S3 buckets across 50 member accounts in AWS Organizations, managed by many teams. The security team must guarantee that no principal outside the organization can access any of these buckets, even if a team writes a bucket policy that grants access to an external AWS account. AWS services acting on the company's behalf must keep working. The control must be central and preventive.","question":"Which solution meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Attach a resource control policy (RCP) to the organization root that denies `s3:*` when `aws:PrincipalOrgID` is not the company's organization ID, with a condition that excludes AWS service principals (`aws:PrincipalIsAWSService` false).","correct":true,"why":"RCPs set the maximum permissions on resources in member accounts no matter who the caller is, so an external principal is blocked even if a bucket policy allows it. Exempting service principals keeps AWS service integrations working."},{"text":"Attach a service control policy (SCP) to the organization root that denies all `s3:*` actions unless the `aws:PrincipalOrgID` condition key matches the company's organization ID, and exempt AWS service principals with an `aws:PrincipalIsAWSService` condition.","correct":false,"why":"SCPs only apply to principals inside the organization's member accounts. A principal in an external account isn't affected by your SCPs, so a permissive bucket policy would still let it in."},{"text":"Enable S3 Block Public Access at the organization level for all accounts.","correct":false,"why":"Block Public Access blocks public (anonymous or any-principal) grants. A bucket policy that names one specific external account ID isn't public, so that access would still be allowed."},{"text":"Enable an IAM Access Analyzer external access analyzer for the organization and send findings to Security Hub.","correct":false,"why":"Access Analyzer detects external access after a policy exists. The requirement is a preventive control that stops the access from working in the first place."}],"takeaway":"SCPs limit your own principals; RCPs limit access to your resources, including by outside principals. A data perimeter uses both.","trap":"Using an SCP to block external principals","services":["Organizations","S3","IAM"]},{"id":"security-006","domain":"security","topic":"Cross-account roles","difficulty":"medium","scenario":"A retailer is onboarding a third-party cost-optimization SaaS vendor that needs read-only access to the retailer's AWS account. The vendor runs its platform in its own AWS account and serves thousands of customers. The retailer's security team is concerned that another vendor customer could trick the vendor into accessing the retailer's account.","question":"Which solution is the MOST secure?","qualifier":"MOST secure","select":1,"options":[{"text":"Create an IAM role with read-only permissions whose trust policy allows the vendor's AWS account as the principal, with a condition requiring `sts:ExternalId` to match a unique value the vendor generated for the retailer.","correct":true,"why":"The external ID protects against the confused deputy problem: the vendor's system must supply this customer's unique ID when calling `AssumeRole`, so another customer can't get the vendor to assume the retailer's role."},{"text":"Create an IAM user with read-only permissions and give the vendor its access key, rotated every 90 days.","correct":false,"why":"Long-term access keys held by a third party are a leakage risk, and rotating them by hand is error-prone. Cross-account roles provide temporary credentials instead."},{"text":"Create an IAM role with read-only permissions whose trust policy allows any principal, with a condition that `aws:PrincipalOrgID` must equal the vendor's AWS Organizations ID, so only identities from the vendor's organization can assume it.","correct":false,"why":"This limits callers to the vendor's organization but doesn't stop the confused deputy problem, because the vendor's own platform makes the call on behalf of any of its customers."},{"text":"Configure an IAM OIDC identity provider pointing to the vendor's login page and allow `AssumeRoleWithWebIdentity`.","correct":false,"why":"OIDC web identity federation is for end users or workloads authenticating with an OIDC provider. It is not the right pattern for an AWS-hosted vendor accessing your account."}],"takeaway":"Third-party cross-account access means an IAM role, a trust policy naming the vendor account, and a unique sts:ExternalId to prevent the confused deputy problem.","trap":"Confused deputy / missing external ID","services":["IAM","STS"]},{"id":"security-007","domain":"security","topic":"Resource-based policies","difficulty":"hard","scenario":"A DevOps engineer is configuring S3 event notifications so that object uploads to bucket `invoices-raw` send messages to an SQS queue in the same account. The queue is encrypted with SSE-KMS using a customer managed key. When the engineer saves the notification configuration, S3 returns `Unable to validate the following destination configurations`. The solution must follow least privilege.","question":"Which combination of changes is required? (Select TWO.)","qualifier":"least privilege","select":2,"options":[{"text":"Add a statement to the SQS queue policy that allows the `s3.amazonaws.com` service principal to call `sqs:SendMessage`, with conditions on `aws:SourceArn` (the bucket ARN) and `aws:SourceAccount`.","correct":true,"why":"S3 delivers notifications as the S3 service principal, so the queue's resource-based policy must allow it. The source conditions stop other buckets or accounts from using that permission (confused deputy protection)."},{"text":"Add a statement to the customer managed KMS key policy that allows the `s3.amazonaws.com` service principal to use `kms:GenerateDataKey` and `kms:Decrypt`.","correct":true,"why":"To send to an SSE-KMS queue, the sender needs permission to generate a data key with the queue's KMS key. S3 has to be allowed in the key policy or the message can't be encrypted."},{"text":"Create an IAM role that S3 can assume with `sqs:SendMessage` permission, and set the role ARN on the bucket notification configuration.","correct":false,"why":"S3 event notifications don't use an IAM role; there's no role setting on the notification configuration. Permission comes only from the destination's resource policy."},{"text":"Change the queue encryption to the AWS managed key `aws/sqs` to avoid editing key policies.","correct":false,"why":"You can't change the key policy of an AWS managed key, and it doesn't allow S3, so notifications to a queue encrypted with `aws/sqs` fail. Use SSE-SQS or a customer managed key."},{"text":"Add a statement to the `invoices-raw` bucket policy that allows the SQS service principal to call `s3:GetObject`.","correct":false,"why":"This grants the wrong service the wrong permission. What's missing is S3's permission to write to the queue and use the key, not SQS reading the bucket."}],"takeaway":"Services that publish to SQS or SNS need the destination's resource policy (service principal plus aws:SourceArn and aws:SourceAccount), and a customer managed key policy when SSE-KMS is used.","trap":"IAM role where a resource policy is needed","services":["S3","SQS","KMS"]},{"id":"security-008","domain":"security","topic":"KMS cross-account","difficulty":"hard","scenario":"Account A (data platform) stores reports in an S3 bucket encrypted with SSE-KMS using a customer managed key in account A. A Lambda function in account B (analytics) must read these objects. The bucket policy already grants the Lambda execution role in account B `s3:GetObject`, but every call returns `AccessDenied` from KMS.","question":"Which combination of changes should be made to grant access with LEAST privilege? (Select TWO.)","qualifier":"LEAST privilege","select":2,"options":[{"text":"In account A, add a statement to the KMS key policy that allows account B's Lambda execution role ARN to call `kms:Decrypt`.","correct":true,"why":"Cross-account KMS use requires the key policy in the key's account to allow the external principal (or the external account). Without it, IAM policies in account B have no effect."},{"text":"In account B, attach an IAM policy to the Lambda execution role that allows `kms:Decrypt` on the full key ARN from account A.","correct":true,"why":"The external account must also grant its own principal permission in an identity policy. Cross-account permissions in IAM policies must reference the key ARN, not an alias."},{"text":"In account B, attach an IAM policy that allows `kms:Decrypt` on `alias/reports-key`.","correct":false,"why":"To control access to a key in another account in an IAM policy, use the key ARN. An alias ARN resource only controls access to the alias, not to the key."},{"text":"Re-encrypt the objects with the AWS managed key `aws/s3` and share it with account B.","correct":false,"why":"You can't edit AWS managed key policies, so they can't be used across accounts. That makes this approach impossible."},{"text":"In account B, create a KMS grant on account A's key for the Lambda role.","correct":false,"why":"Account B can only create a grant if account A's key policy already allows it to call `kms:CreateGrant`. Even then, a grant adds complexity without solving the missing key policy permission."}],"takeaway":"Cross-account KMS needs both: the key policy in the key owner account and an IAM policy in the caller account referencing the key ARN. AWS managed keys can't be shared.","trap":"Only one side of cross-account KMS / aws-managed key","services":["KMS","S3","Lambda","IAM"]},{"id":"security-009","domain":"security","topic":"KMS multi-Region keys","difficulty":"medium","scenario":"A fintech company encrypts sensitive fields on the client side with the AWS Encryption SDK and a KMS key in us-east-1, then stores the ciphertext in a DynamoDB global table that replicates to eu-west-1. For disaster recovery, the application in eu-west-1 must be able to decrypt the data even if us-east-1 is completely unavailable, without re-encrypting the data.","question":"Which solution meets these requirements?","qualifier":null,"select":1,"options":[{"text":"Use a KMS multi-Region primary key in us-east-1 and create a replica key in eu-west-1. Decrypt in eu-west-1 by calling KMS in that Region with the replica key.","correct":true,"why":"Multi-Region keys share the same key material and key ID across Regions, so ciphertext produced in one Region can be decrypted locally by the replica without calling the original Region."},{"text":"Keep the single-Region key and have the eu-west-1 application call the us-east-1 KMS endpoint to decrypt.","correct":false,"why":"This keeps a hard dependency on us-east-1. If that Region is down, decryption fails, which breaks the DR requirement."},{"text":"Create a new single-Region customer managed key in eu-west-1 and give it the same alias as the us-east-1 key. The Encryption SDK resolves the alias in whichever Region the application runs in, so the eu-west-1 application can decrypt locally.","correct":false,"why":"Aliases are per Region, and a different key has different key material. Ciphertext from the us-east-1 key can't be decrypted by an unrelated key."},{"text":"Enable automatic key rotation on the us-east-1 key, which also copies the key material to the other Regions where the table is replicated.","correct":false,"why":"Automatic rotation only creates new key material for the same key in the same Region. It never copies keys to other Regions."}],"takeaway":"Multi-Region KMS keys let you decrypt in another Region without cross-Region calls. Aliases and single-Region keys don't carry over between Regions.","trap":"Assuming aliases/rotation make keys multi-Region","services":["KMS","DynamoDB"]},{"id":"security-010","domain":"security","topic":"Secrets Manager rotation","difficulty":"hard","scenario":"A company runs a vendor-supplied application on ECS that connects to an Amazon RDS for PostgreSQL database with a username and password. The application can't generate IAM authentication tokens, but it can read credentials from a configured secret store at startup and when a connection fails. A new policy requires the application's database password to be rotated automatically every 30 days without application downtime.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Store the credentials in AWS Secrets Manager and turn on rotation every 30 days using the AWS-provided PostgreSQL rotation function with the alternating-users strategy.","correct":true,"why":"Secrets Manager rotation is native and uses AWS-provided Lambda rotation templates. The alternating-users strategy keeps one valid set of credentials at all times while the other is rotated, which avoids downtime."},{"text":"Store the password as a Systems Manager Parameter Store `SecureString` parameter and enable its built-in rotation schedule.","correct":false,"why":"Parameter Store has no built-in rotation. Policies on advanced parameters can only expire (delete) a parameter or send EventBridge notifications; they never change the database password."},{"text":"Store the password in Parameter Store as a `SecureString`. Create an EventBridge Scheduler schedule that runs every 30 days and invokes a custom Lambda function, which generates a new password, changes it in PostgreSQL, and updates the parameter.","correct":false,"why":"This works, but you'd have to write and maintain rotation logic, including the steps that avoid downtime, which Secrets Manager already provides."},{"text":"Enable IAM database authentication on the RDS instance so passwords are no longer needed.","correct":false,"why":"The vendor application can't generate IAM authentication tokens, so this doesn't meet the stated constraint."}],"takeaway":"Secrets Manager rotates natively, with an alternating-users option for zero downtime. Parameter Store SecureString has no native rotation.","trap":"Parameter Store 'rotation'","services":["Secrets Manager","Systems Manager","RDS"]},{"id":"security-011","domain":"security","topic":"ECS task roles","difficulty":"hard","scenario":"A media company is moving a service to ECS on Fargate. The task definition pulls an image from a private ECR repository, sends logs with the `awslogs` driver, and injects a database password from Secrets Manager (encrypted with a customer managed KMS key) as an environment variable using the container definition's `secrets` field. At runtime, the application code uploads files to an S3 bucket. Tasks currently fail to start with `ResourceInitializationError: unable to pull secrets`.","question":"Which combination of IAM changes should the engineer make to follow LEAST privilege? (Select TWO.)","qualifier":"LEAST privilege","select":2,"options":[{"text":"Grant the task execution role `secretsmanager:GetSecretValue` on the specific secret ARN and `kms:Decrypt` on the customer managed key.","correct":true,"why":"The ECS agent uses the task execution role to pull images, write logs, and fetch values referenced in `secrets` before the container starts. A secret encrypted with a customer managed key also needs `kms:Decrypt`."},{"text":"Grant the task role `s3:PutObject` on the target bucket.","correct":true,"why":"Application code in the container gets credentials from the task role (`taskRoleArn`). Calls the app makes, like S3 uploads, must be allowed there."},{"text":"Grant the task role `secretsmanager:GetSecretValue` and `kms:Decrypt`, since the secret is used by the application.","correct":false,"why":"Values in the `secrets` field are injected by the ECS agent before the container starts, using the execution role. The task role is only used by code running inside the container."},{"text":"Add the permissions to the container instance IAM role so all tasks on the host inherit them.","correct":false,"why":"Fargate has no container instances you manage. Even on EC2, using the instance role for every task goes against least privilege."},{"text":"Store the password as a Docker Swarm secret and mount it into the task.","correct":false,"why":"ECS doesn't support Docker Swarm secrets. ECS uses Secrets Manager or Parameter Store references through the `secrets` field."}],"takeaway":"The execution role is for the ECS agent (image pull, logs, injecting secrets); the task role is for your application's own AWS API calls.","trap":"Task execution role vs task role","services":["ECS","IAM","Secrets Manager","KMS"]},{"id":"security-012","domain":"security","topic":"EKS Pod Identity","difficulty":"hard","scenario":"A platform team runs 25 Amazon EKS clusters and creates new clusters often, through blue/green cluster upgrades. Workloads in the `payments` namespace need access to a DynamoDB table using a shared IAM role. Today the team uses IAM roles for service accounts (IRSA) and has to update the role's trust policy with each new cluster's OIDC provider, and has occasionally hit trust policy size limits. Pods must not use the node's instance role.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Install the Amazon EKS Pod Identity Agent add-on in each cluster, give the IAM role a trust policy for the `pods.eks.amazonaws.com` service principal (`sts:AssumeRole` and `sts:TagSession`), and create a pod identity association for the `payments` namespace and service account in each cluster.","correct":true,"why":"With EKS Pod Identity, the role trusts one service principal no matter which cluster is calling, so new clusters only need an association. No OIDC provider or trust policy edits are required."},{"text":"Keep using IRSA, but change the role's trust policy to use a wildcard in the `Federated` principal (`arn:aws:iam::<account>:oidc-provider/oidc.eks.<region>.amazonaws.com/id/*`) with a `StringLike` condition on the `sub` claim for `system:serviceaccount:payments:*`.","correct":false,"why":"The `Federated` principal in a trust policy can't use wildcards for OIDC providers. Each cluster's provider has to be listed, which is the limitation they're hitting."},{"text":"Attach the DynamoDB permissions to the managed node group's instance role.","correct":false,"why":"This gives the permissions to every pod on those nodes and breaks the requirement that pods must not use the node role."},{"text":"Create an IAM user with DynamoDB permissions and store its access keys in a Kubernetes Secret in the `payments` namespace.","correct":false,"why":"Long-term keys in Kubernetes Secrets are a security risk and need manual rotation. Pod-level IAM roles provide temporary credentials."}],"takeaway":"EKS Pod Identity removes per-cluster OIDC trust management: one pods.eks.amazonaws.com trust policy plus a pod identity association per cluster.","trap":"IRSA per-cluster OIDC trust overhead","services":["EKS","IAM","DynamoDB"]},{"id":"security-013","domain":"security","topic":"GuardDuty","difficulty":"hard","scenario":"A company with 70 accounts in AWS Organizations wants Amazon GuardDuty enabled in every account and Region it uses, including accounts created later. The security team, which works from a dedicated security tooling account, must get an email for every finding with high or critical severity from any account, using as few components as possible.","question":"Which combination of steps meets these requirements with the LEAST operational overhead? (Select TWO.)","qualifier":"LEAST operational overhead","select":2,"options":[{"text":"From the management account, designate the security tooling account as the GuardDuty delegated administrator in each Region, and set auto-enable for all organization members (`ALL`) in the GuardDuty organization configuration.","correct":true,"why":"A delegated administrator with org auto-enable turns GuardDuty on for existing and new member accounts, and all member findings are collected in the administrator account."},{"text":"In the delegated administrator account, in each Region, create an EventBridge rule matching `source` `aws.guardduty` with a numeric event pattern on `detail.severity` `>= 7`, targeting an SNS topic with the team's email subscribed.","correct":true,"why":"GuardDuty sends findings to EventBridge, including member findings in the administrator account. A numeric match on severity covers High (7.0 to 8.9) and Critical (9.0 to 10.0)."},{"text":"Subscribe the security team's email address directly to GuardDuty finding notifications in the GuardDuty console.","correct":false,"why":"GuardDuty has no direct SNS or email subscription for findings. Notifications go through EventBridge, optionally with Security Hub in the path."},{"text":"Enable Amazon Detective in the security tooling account and configure it to email high-severity findings.","correct":false,"why":"Detective helps investigate findings with behavior graphs. It doesn't detect threats or send alerts, so it adds cost without meeting the requirement."},{"text":"Use CloudFormation StackSets to enable a GuardDuty detector and an EventBridge rule in every member account and Region.","correct":false,"why":"This works, but it duplicates rules and topics in every account and doesn't centralize findings. Org auto-enable and a central rule have much less overhead."}],"takeaway":"GuardDuty at org scale: a delegated admin with auto-enable ALL, then an EventBridge rule in the admin account (severity >= 7) to SNS. GuardDuty never publishes to SNS directly.","trap":"GuardDuty doesn't publish directly to SNS; Detective doesn't alert","services":["GuardDuty","EventBridge","SNS","Organizations"]},{"id":"security-014","domain":"security","topic":"Security Hub","difficulty":"hard","scenario":"A company uses AWS Security Hub CSPM across 40 accounts in four Regions, with a delegated administrator account. Security analysts complain that they must switch Regions to see findings, and that one control (`EC2.8`, IMDSv2 required) floods them with findings from sandbox accounts, where the risk has been formally accepted. The team wants one place to see all findings and wants new sandbox findings for that control suppressed automatically, without custom code.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"In the delegated administrator account, designate a home (aggregation) Region that links the other three Regions. Create a Security Hub automation rule that matches control ID `EC2.8` and the sandbox account IDs and sets the workflow status to `SUPPRESSED`.","correct":true,"why":"Cross-Region aggregation copies findings from linked Regions into the home Region. Automation rules update matching findings as they're created or updated (for example, setting workflow status to `SUPPRESSED`) without Lambda."},{"text":"In each Region, create an EventBridge rule for `Security Hub Findings - Imported` events that invokes a Lambda function. The function calls `BatchUpdateFindings` to set the workflow status of `EC2.8` findings from sandbox accounts to `SUPPRESSED`, and analysts switch Regions to review the rest.","correct":false,"why":"This was the pattern before automation rules existed. It works, but it adds custom code in every Region and doesn't solve viewing findings across Regions."},{"text":"Create an AWS Config aggregator in the delegated administrator account and delete the `ec2-imdsv2-check` rule from sandbox accounts.","correct":false,"why":"A Config aggregator shows compliance data, not Security Hub findings. Security Hub manages its own service-linked Config rules, so deleting one by hand gets reverted or breaks the control instead of suppressing findings cleanly."},{"text":"Use AWS Audit Manager with a custom framework that excludes the sandbox accounts, and have analysts use Audit Manager instead of Security Hub.","correct":false,"why":"Audit Manager collects audit evidence for compliance frameworks. It isn't a findings triage tool and has no cross-Region findings aggregation or suppression rules."}],"takeaway":"Security Hub cross-Region aggregation gives one pane of glass; automation rules suppress or adjust findings without Lambda.","trap":"Custom Lambda vs native automation rules","services":["Security Hub","AWS Config","Audit Manager"]},{"id":"security-015","domain":"security","topic":"Amazon Inspector","difficulty":"medium","scenario":"A healthcare SaaS provider runs workloads on EC2 instances, container images stored in Amazon ECR, and Lambda functions across 20 accounts in AWS Organizations. Compliance requires continuous scanning for software vulnerabilities (CVEs) in all three, automatic rescanning when new CVEs are published, and a single organization-wide view of the results.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Designate a delegated administrator for Amazon Inspector and enable EC2 scanning, ECR enhanced scanning, and Lambda scanning, with auto-enable for all member accounts.","correct":true,"why":"Inspector continuously scans EC2 (through the SSM agent or agentless), ECR images (enhanced scanning), and Lambda functions for CVEs, rescans automatically when new CVEs are published, and combines results in the delegated administrator account."},{"text":"Turn on Amazon ECR basic scanning with scan on push for every repository in all accounts, and use AWS Systems Manager Patch Manager compliance reports to track missing operating system patches on the EC2 instances, combining both in a shared dashboard.","correct":false,"why":"Basic scanning only covers container images, not Lambda, and doesn't continuously rescan as new CVEs appear. Patch compliance reports missing patches, not a CVE inventory, so this leaves gaps and splits the results across tools."},{"text":"Enable GuardDuty Malware Protection for EC2 and ECS and GuardDuty Lambda Protection organization-wide.","correct":false,"why":"GuardDuty detects threats and malware (and Lambda Protection watches network activity). It doesn't do CVE scanning of software packages."},{"text":"Enable Amazon Macie organization-wide with automated sensitive data discovery.","correct":false,"why":"Macie finds sensitive data such as PII in S3. It doesn't scan compute for vulnerabilities."}],"takeaway":"Inspector = CVE scanning for EC2, ECR, and Lambda; GuardDuty = threats and malware; Macie = sensitive data in S3.","trap":"Inspector vs GuardDuty vs Macie","services":["Inspector","ECR","Lambda","EC2"]},{"id":"security-016","domain":"security","topic":"CloudTrail protection","difficulty":"hard","scenario":"A regulated bank must keep API activity logs for all 90 accounts in its organization for 7 years. Auditors require that administrators in member accounts can't disable or change logging, that log files can't be deleted or overwritten by anyone (including administrators) during retention, and that the bank can prove a log file wasn't modified after delivery.","question":"Which combination of steps meets these requirements? (Select THREE.)","qualifier":null,"select":3,"options":[{"text":"Create an organization trail from the management account (or the CloudTrail delegated administrator) that logs all Regions.","correct":true,"why":"An organization trail is created automatically in every member account, and member accounts can see it but can't modify or delete it, so local administrators can't turn off logging."},{"text":"Deliver the logs to an S3 bucket in a dedicated log archive account that has S3 Object Lock in compliance mode with a 7-year default retention period.","correct":true,"why":"In compliance mode, no user, including the root user, can delete or overwrite object versions until retention ends. Using a separate account also isolates the logs from workload administrators."},{"text":"Enable CloudTrail log file integrity validation.","correct":true,"why":"CloudTrail delivers signed digest files (SHA-256 with RSA). Running `validate-logs` proves whether log files were modified, deleted, or forged after delivery."},{"text":"Deploy the `cloudtrail-enabled` AWS Config rule in every account with an SNS notification.","correct":false,"why":"This only detects that logging was disabled after it happens. It doesn't prevent tampering or deletion."},{"text":"Use S3 Object Lock in governance mode so the security team can delete logs if needed.","correct":false,"why":"Governance mode lets users with `s3:BypassGovernanceRetention` delete objects, which breaks the requirement that no one, including administrators, can delete logs."},{"text":"Encrypt the log files with SSE-S3 and enable S3 Versioning on the bucket in the management account.","correct":false,"why":"Versioning helps recovery, but privileged users can still delete versions, and SSE-S3 provides no integrity proof. Storing logs in the management account also goes against the log archive isolation best practice."}],"takeaway":"Tamper-proof audit trail = organization trail + Object Lock compliance mode in a log archive account + log file integrity validation.","trap":"Governance vs compliance mode; detect vs prevent","services":["CloudTrail","S3","Organizations"]},{"id":"security-017","domain":"security","topic":"Firewall Manager","difficulty":"hard","scenario":"A retail group with 60 accounts in AWS Organizations must ensure that every internet-facing Application Load Balancer and CloudFront distribution, including ones created later by any team, is protected by an AWS WAF web ACL with the AWS Managed Rules core rule set and a company-specific rate-based rule. Resources that don't comply must be fixed automatically, and the security team wants one place to manage the rules.","question":"Which solution meets these requirements with the LEAST operational overhead?","qualifier":"LEAST operational overhead","select":1,"options":[{"text":"Designate a Firewall Manager administrator account, make sure AWS Config is enabled in member accounts, and create Firewall Manager AWS WAF policies (one Regional for ALBs, one global for CloudFront) that include the required rule groups, with automatic remediation turned on and scope set to the organization.","correct":true,"why":"Firewall Manager deploys and associates WAF web ACLs across accounts, applies them to new resources in scope, and fixes non-compliant resources. It requires Organizations and AWS Config."},{"text":"Subscribe all accounts to AWS Shield Advanced, which automatically applies the AWS Managed Rules core rule set to protected resources.","correct":false,"why":"Shield Advanced adds DDoS protection, response team support, and cost protection. It doesn't deploy the core rule set or custom rate-based rules to every resource across the organization."},{"text":"Deploy AWS Network Firewall in every VPC with stateful rule groups that use the AWS managed threat signature rule groups.","correct":false,"why":"Network Firewall inspects VPC traffic, not ALB or CloudFront at layer 7 the way WAF does. It can't protect CloudFront distributions and isn't the required WAF web ACL."},{"text":"Use CloudFormation StackSets with service-managed permissions to deploy a WAF web ACL containing the core rule set and the rate-based rule to every account and Region, and document that teams must associate the web ACL with each new ALB or distribution.","correct":false,"why":"This creates the web ACLs but relies on teams to attach them, so new resources can be left unprotected and nothing remediates automatically."}],"takeaway":"Firewall Manager centrally enforces WAF, Shield Advanced, security group, and Network Firewall policies across an organization, including for new resources.","trap":"Shield Advanced/Network Firewall vs WAF via Firewall Manager","services":["Firewall Manager","WAF","Shield","Network Firewall","Organizations"]}];
